window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[34] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נק׳) הוכיחו את המשפט השני של ויירשטראס (משפט 5.37): פונקציה רציפה בקטע סגור מקבלת בו מינימום ומקסימום. מספיק להוכיח רק את קיום המקסימום.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה רציפה שמוגדרת על קטע סגור לא יכולה &quot;לעצור רגע לפני השיא&quot; — חייבת להיות בתוך הקטע נקודה שבה היא ממש מגיעה לגובה המרבי.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה רציפה שמוגדרת על קטע סגור לא יכולה &quot;לעצור רגע לפני השיא&quot; — חייבת להיות בתוך הקטע נקודה שבה היא ממש מגיעה לגובה המרבי.</p>\n<p><strong>תמונה בראש</strong>: דמיינו שביל הליכה רציף בין שער כניסה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>)</span> לשער יציאה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>),</span> ושני השערים פתוחים למטיילים. קבוצת הגבהים לא יכולה לעלות עד אינסוף, ולכן יש לה תקרה נמוכה ביותר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> אם נשלח רצים שיתקרבו <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> יותר ויותר, כי המסלול סגור ותחום, תת-קבוצה שלהם תתכנס לנקודה אחת <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> בתוך המסלול עצמו — ובגלל הרציפות, הגובה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> יהיה שווה בדיוק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,4]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x(4-x)\\)</span> מגיעה לגובה המרבי <span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=2\\)</span>.</span> לעומת זאת, אם פותחים את הקצה בפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,4)\\)</span>,</span> הערכים מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(3.9, 3.99, 3.999\\)</span>)</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span> עצמה אינה בקטע ואין מקסימום.</p>\n<p><strong>חסם עליון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span>)</span></strong> הוא &quot;התקרה הכי נמוכה&quot;: המספר הקטן ביותר שעדיין לא קטן מאף איבר בקבוצה. <strong>מקסימום</strong> הוא תקרה כזאת שהקבוצה גם מכילה אותה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>חשבו על <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> כעל קבוצת כל הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לחצו על <strong>קבעו <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span></strong>, והקטינו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>:</span> בכל פעם תופיע נקודה ירוקה מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\varepsilon\\)</span>,</span> בדיוק כמו שבשלב השני בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)&gt;M-\\frac1n\\)</span>.</span></span></p>\n<figure class=\"demo\" id=\"demo-sup\" data-demo=\"sup\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: למה בכלל יש מועמד למקסימום","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: למה בכלל יש מועמד למקסימום</p><div class=\"callout-body\"><p>השתמשו קודם במשפט ויירשטראס הראשון (משפט 5.35): מה הוא מבטיח על קבוצת הערכים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f([a,b])\\)</span>?</span> זה נותן קיום של חסם עליון סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup f([a,b])\\)</span>.</span></p></div></div>"},{"title":"רמז 2: בונים סדרת מתקרבים ל-$M$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בונים סדרת מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span></p><div class=\"callout-body\"><p>השתמשו באפיון הסופרמום (טענה 3.9) עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac1n\\)</span> כדי למצוא נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n&lt;f(x_n)\\le M\\)</span>.</span></span> מה גבול הסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\)</span>?</span></p></div></div>"},{"title":"רמז 3: עוברים לתת-סדרה בתוך הקטע הסגור","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: עוברים לתת-סדרה בתוך הקטע הסגור</p><div class=\"callout-body\"><p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> נמצאת בתוך <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> ולכן חסומה. הוציאו ממנה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\)</span> בעזרת בולצאנו-ויירשטראס (משפט 3.32), הראו <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span></span> והשוו את הגבולות של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_{n_k})\\)</span> (היינה מול תת-סדרה).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ממשפט ויירשטראס הראשון קבוצת הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה ולכן יש לה חסם עליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> מאפיון הסופרמום נבנה סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> בקטע כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></span> ממשפט בולצאנו-ויירשטראס נוציא תת-סדרה המתכנסת לנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span> ומרציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: קיום החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> כלומר קבוצת התמונה <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x):x\\in[a,b]\\}\\)</span> חסומה (היא אינה ריקה, כי למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>).</span> לפי אקסיומת השלמות (משפט 3.6), קיים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> חסם עליון סופי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M=\\sup\\{f(x):x\\in[a,b]\\}.\\]</div>\n<p><strong>שלב 2: בניית סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> המקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span></span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\)</span> קטן מהסופרמום <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> ולכן לפי טענה 3.9 אינו חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>.</span> לכן קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac1n&lt;f(x_n)\\le M.\\]</div>\n<p><em>למה?</em> בכל צעד <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אנו מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> עד כדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span>,</span> כדי להכריח את ערכי הפונקציה על הסדרה לשאוף אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\to M\\)</span></span> והסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\to M\\)</span>,</span> נובע ממשפט הסנדוויץ׳ (משפט 2.32) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}f(x_n)=M\\)</span>.</span></p>\n<p><strong>שלב 3: בחירת תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> כלומר הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p>כיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span>,</span> ומשפט 2.31 קובע כי גבול של סדרות שומר על אי-שוויון חלש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><em>למה?</em> בזכות סגירות הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> של תת-הסדרה חייב להישאר בתחום ההגדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>.</span></p>\n<p><strong>שלב 4: הסקת <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span> וסיום.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></span> לפי אפיון היינה של רציפות (טענה 5.4), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=f(c)\\)</span>.</span></p>\n<p>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span>,</span> ולכן לפי משפט 3.25 היא שואפת לאותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> לפי יחידות הגבול של סדרה (משפט 2.12), <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> הוא חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>.</span> לפי הגדרה 5.36, <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> הוא המקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: קיום החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> כלומר קבוצת התמונה <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x):x\\in[a,b]\\}\\)</span> חסומה (היא אינה ריקה, כי למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>).</span> לפי אקסיומת השלמות (משפט 3.6), קיים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> חסם עליון סופי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M=\\sup\\{f(x):x\\in[a,b]\\}.\\]</div>","<p><strong>שלב 2: בניית סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> המקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>.</span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span></span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\)</span> קטן מהסופרמום <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> ולכן לפי טענה 3.9 אינו חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>.</span> לכן קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac1n&lt;f(x_n)\\le M.\\]</div>\n<p><em>למה?</em> בכל צעד <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אנו מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> עד כדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span>,</span> כדי להכריח את ערכי הפונקציה על הסדרה לשאוף אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac1n\\to M\\)</span></span> והסדרה הקבועה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\to M\\)</span>,</span> נובע ממשפט הסנדוויץ׳ (משפט 2.32) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}f(x_n)=M\\)</span>.</span></p>","<p><strong>שלב 3: בחירת תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> כלומר הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת תת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p>כיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span>,</span> ומשפט 2.31 קובע כי גבול של סדרות שומר על אי-שוויון חלש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><em>למה?</em> בזכות סגירות הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> של תת-הסדרה חייב להישאר בתחום ההגדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>.</span></p>","<p><strong>שלב 4: הסקת <span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span> וסיום.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></span> לפי אפיון היינה של רציפות (טענה 5.4), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=f(c)\\)</span>.</span></p>\n<p>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span>,</span> ולכן לפי משפט 3.25 היא שואפת לאותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> לפי יחידות הגבול של סדרה (משפט 2.12), <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> הוא חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>.</span> לפי הגדרה 5.36, <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> הוא המקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> עצמה מתכנסת ולשכוח להפעיל את משפט בולצאנו-ויירשטראס (משפט 3.32) למעבר לתת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span>.</span></li><li>לשכוח להוכיח כי <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span> באמצעות משפט 2.31 על אי-השוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":null},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו את משפט הסנדוויץ׳ (משפט 2.32):</p>\n<p>תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n), (b_n)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span></span> סדרות עבורן מתקיימים התנאים הבאים:</p>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\le b_n\\le c_n\\)</span>;</span> הסדרות <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span></span> מתכנסות; <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n\\)</span>.</span></span></p>\n<p>אז גם הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתכנסת, ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}b_n=\\lim_{n\\to\\infty}c_n\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> המקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=\\lim_{x\\to b^-}f(x)=\\infty\\)</span>.</span> הוכיחו שקיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>.</span></span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">אם שני קירות מתקרבים לאותו גובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> ומישהו לכוד ביניהם, גם הוא חייב להגיע לגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: אם שני קירות מתקרבים לאותו גובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> ומישהו לכוד ביניהם, גם הוא חייב להגיע לגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: שני חברים הולכים משני צדיכם ומתקרבים בדיוק אל אותו קו מטרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span> מבקשים מכם להגיע למרחק <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> מהקו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span> ברגע שהחבר שמשמאל נכנס לאזור <span class=\"math math-inline\" dir=\"ltr\">\\((L-\\varepsilon,L+\\varepsilon)\\)</span> והחבר שמימין גם הוא נכנס לאותו אזור — אתם, שלכודים תמיד ביניהם, נמצאים שם בעל כורחכם!</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=-\\frac1n\\to 0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n=\\frac1n\\to 0\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n=\\frac{\\sin n}{n}\\)</span></span> כלואה תמיד בין <span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac1n\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span>.</span></span> אם דורשים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=0.1\\)</span>,</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;10\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-0.1&lt;a_n\\le b_n\\le c_n&lt;0.1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n-0|&lt;0.1\\)</span>.</span></p>\n<p><strong>סדרה מתכנסת לגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></strong> פירושו שלכל רוחב <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> של חלון סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> קיים מקום שממנו כל איברי הסדרה נמצאים בתוך החלון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((L-\\varepsilon,L+\\varepsilon)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הקווים האפורים המקווקווים הם החסמים <span class=\"math math-inline\" dir=\"ltr\">\\(a(x)=-\\frac1x\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c(x)=\\frac1x\\)</span>,</span></span> וביניהם לכודה <span class=\"math math-inline\" dir=\"ltr\">\\(b(x)=\\frac{\\sin(3x)}{x}\\)</span> (בכחול). הקטינו את <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> (המשחק את תפקיד <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> ברצועה האדומה): מהרגע ששני החסמים נכנסים לתוך הרצועה (מעבר לקו הירוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac1k\\)</span>),</span> גם הגרף הכחול שביניהם כלוא כולו בפנים!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.4,&quot;xmax&quot;:14,&quot;ymin&quot;:-1.2,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;k&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;k=0.25&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.1,&quot;max&quot;:0.8,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a(x)=-\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;c&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;c(x)=\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;b(x)=\\\\frac{\\\\sin(3\\\\cdot x)}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=\\\\frac{1}{k}&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: סמנו שם משותף לגבול","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: סמנו שם משותף לגבול</p><div class=\"callout-body\"><p>נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n\\)</span>.</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שני מקומות מתאימים מהגדרת הגבול","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שני מקומות מתאימים מהגדרת הגבול</p><div class=\"callout-body\"><p>הפעילו את הגדרה 2.9 פעמיים: קבלו <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span>.</span> איך מוודאים ששני התנאים יתקיימו יחד מאותו מקום והלאה?</p></div></div>"},{"title":"רמז 3: בונים שרשרת אי-שוויונים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: בונים שרשרת אי-שוויונים</p><div class=\"callout-body\"><p>בחרו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\max\\{N_1,N_2\\}\\)</span>.</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;a_n\\le b_n\\le c_n&lt;L+\\varepsilon\\)</span>.</span> למה זה אומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n-L|&lt;\\varepsilon\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נסמן את הגבול המשותף <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></span> עבור כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> נמצא ממתי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> נכנסת מעל <span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon\\)</span> וממתי <span class=\"math math-inline\" dir=\"ltr\">\\(c_n\\)</span> נכנסת מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>.</span></span> ניקח את המקסימום <span class=\"math math-inline\" dir=\"ltr\">\\(N=\\max\\{N_1,N_2\\}\\)</span> כדי ששני התנאים יתקיימו יחד, ונקבל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> לכודה בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((L-\\varepsilon,L+\\varepsilon)\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: תרגום הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> לפי הגדרה 2.9.</strong> נסמן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> את הגבול המשותף:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n.\\]</div>\n<p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L|&lt;\\varepsilon\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;a_n\\)</span>.</span></li><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}c_n=L\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|c_n-L|&lt;\\varepsilon\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n&lt;L+\\varepsilon\\)</span>.</span></li></ul>\n<p><strong>שלב 2: איחוד המקומות וכליאת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>.</span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\max\\{N_1,N_2\\}\\in\\mathbb N\\)</span>.</span></p>\n<p><em>למה?</em> אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> גדול מהמקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span>,</span></span> הוא גדול מכל אחד מהם בנפרד, וכך גם החסם התחתון של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> וגם החסם העליון של <span class=\"math math-inline\" dir=\"ltr\">\\(c_n\\)</span> תקפים באותו הזמן.</p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span>,</span> גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> וגם נתון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\le b_n\\le c_n\\)</span>.</span></span> נשרשר את אי-השוויונים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L-\\varepsilon&lt;a_n\\le b_n\\le c_n&lt;L+\\varepsilon.\\]</div>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;b_n&lt;L+\\varepsilon\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n-L|&lt;\\varepsilon\\)</span>.</span></p>\n<p>לפי הגדרה 2.9, הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתכנסת ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}b_n=L=\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: תרגום הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> לפי הגדרה 2.9.</strong> נסמן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> את הגבול המשותף:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n.\\]</div>\n<p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L|&lt;\\varepsilon\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;a_n\\)</span>.</span></li><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}c_n=L\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|c_n-L|&lt;\\varepsilon\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n&lt;L+\\varepsilon\\)</span>.</span></li></ul>","<p><strong>שלב 2: איחוד המקומות וכליאת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>.</span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\max\\{N_1,N_2\\}\\in\\mathbb N\\)</span>.</span></p>\n<p><em>למה?</em> אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> גדול מהמקסימום של <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span>,</span></span> הוא גדול מכל אחד מהם בנפרד, וכך גם החסם התחתון של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> וגם החסם העליון של <span class=\"math math-inline\" dir=\"ltr\">\\(c_n\\)</span> תקפים באותו הזמן.</p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span>,</span> גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> וגם נתון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\le b_n\\le c_n\\)</span>.</span></span> נשרשר את אי-השוויונים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L-\\varepsilon&lt;a_n\\le b_n\\le c_n&lt;L+\\varepsilon.\\]</div>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;b_n&lt;L+\\varepsilon\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b_n-L|&lt;\\varepsilon\\)</span>.</span></p>\n<p>לפי הגדרה 2.9, הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתכנסת ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}b_n=L=\\lim_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}c_n\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להשתמש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span></span> אחד עבור שתי הסדרות בלי לציין <span class=\"math math-inline\" dir=\"ltr\">\\(N=\\max\\{N_1,N_2\\}\\)</span> (הן לא חייבות להיכנס לסביבה של <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> באותו אינדקס בדיוק).</li><li>לכתוב <span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\le c_n\\)</span> ולשכוח את הכליאה התחתונה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L-\\varepsilon&lt;a_n\\le b_n\\)</span>:</span> חסם מצד אחד בלבד לא מוכיח התכנסות!</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה גזירה שבשני הקצוות של הקטע הפתוח מטפסת לאינסוף מוכרחה לרדת ואז לעלות, ולכן איפשהו באמצע יש לה תחתית שבה המשיק אופקי.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה גזירה שבשני הקצוות של הקטע הפתוח מטפסת לאינסוף מוכרחה לרדת ואז לעלות, ולכן איפשהו באמצע יש לה תחתית שבה המשיק אופקי.</p>\n<p><strong>תמונה בראש</strong>: דמיינו עמק בצורת קערה פתוחה בין שני קירות תלולים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>).</span></span> קרוב מאוד לקיר השמאלי המדרון גבוה בשמיים, וקרוב מאוד לקיר הימני המדרון גם גבוה בשמיים. אם תבחרו נקודת גובה כלשהי באמצע העמק (<span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>),</span></span> ותחתכו את הקערה בשני מקומות שקרובים לקצוות ושגובהם גבוה יותר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\)</span>,</span></span> יישאר קטע סגור של העמק שמקבל את הנקודה הנמוכה ביותר שלו איפשהו בפנים — ושם הקרקע שטוחה לגמרי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>).</span></p>\n<p><strong>עם מספרים</strong>: בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>,</span> לפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac1x+\\frac{1}{2-x}\\)</span> יש ערך <span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=2\\)</span> באמצע. ליד <span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span> (<span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.1\\)</span>)</span></span> היא מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span>,</span> וליד <span class=\"math math-inline\" dir=\"ltr\">\\(2^-\\)</span> (<span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.9\\)</span>)</span></span> היא גם מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span>.</span> על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0.1,1.9]\\)</span> יש מינימום, והוא חייב להתקבל בפנים (ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=1\\)</span>),</span></span> שם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(1)=0\\)</span>.</span></p>\n<p><strong>משפט פרמה</strong> קובע שאם לפונקציה גזירה יש נקודת קיצון (מקסימום או מינימום) פנימית, הנגזרת שם חייבת להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac1x+\\frac{1}{2-x}\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span> (בין הקירות האפורים המקווקווים <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=2\\)</span>).</span></span> משני הצדדים הוא עולה לאינסוף, כך שמחויב להיווצר עמק עם מינימום בנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((1,2)\\)</span> ומשיק אופקי אדום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=2\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לעקוב אחרי הירידה והעלייה דרך המינימום.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:2.3,&quot;ymin&quot;:0,&quot;ymax&quot;:12}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.5&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.15,&quot;max&quot;:1.85,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{1}{x}+\\\\frac{1}{2-x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;wa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;tan&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pm&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,2)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קיצוץ הקצוות לקטע סגור","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קיצוץ הקצוות לקטע סגור</p><div class=\"callout-body\"><p>אי אפשר להפעיל ישר את ויירשטראס על <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> כי הקטע פתוח והפונקציה לא חסומה. בחרו נקודת ייחוס <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\in(a,b)\\)</span> והשתמשו בגבולות האינסופיים כדי לקצץ משמאל ומימין לקטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\subset(a,b)\\)</span>.</span></p></div></div>"},{"title":"רמז 2: מוודאים שהמינימום אינו בקצוות $\\alpha$ ו-$\\beta$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מוודאים שהמינימום אינו בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span></span></p><div class=\"callout-body\"><p>בחרו <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span> קרוב מספיק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\alpha)&gt;f(x_0)\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span></span> קרוב מספיק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(\\beta)&gt;f(x_0)\\)</span></span> (כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha&lt;x_0&lt;\\beta\\)</span>).</span> מי אינו יכול להיות נקודת המינימום של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span>?</span></p></div></div>"},{"title":"רמז 3: סגירה עם משפט פרמה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: סגירה עם משפט פרמה</p><div class=\"callout-body\"><p>ממשפט ויירשטראס השני (משפט 5.37) <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מינימום בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[\\alpha,\\beta]\\)</span>.</span> מדוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(\\alpha,\\beta)\\)</span>?</span> ולאחר מכן הפעילו את משפט פרמה (משפט 8.4).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נבחר נקודת השוואה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\in(a,b)\\)</span>.</span> מהנתונים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=\\lim_{x\\to b^-}f(x)=\\infty\\)</span> נמצא <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\in(a,x_0)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\in(x_0,b)\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(\\alpha)&gt;f(x_0)\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\beta)&gt;f(x_0)\\)</span>.</span></span> על הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span>,</span> הפונקציה רציפה ולכן מקבלת מינימום <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[\\alpha,\\beta]\\)</span> (משפט 5.37); מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x_0)\\)</span>,</span></span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> היא פנימית ולפי משפט פרמה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: רציפות של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> ובחירת נקודת השוואה.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> (משפט 7.9). נבחר נקודה כלשהי באמצע הקטע, למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0=\\frac{a+b}{2}\\in(a,b)\\)</span>,</span> ונסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=f(x_0)\\)</span>.</span></p>\n<p><strong>שלב 2: חיתוך הקטע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\subset(a,b)\\)</span>.</span></span></strong></p>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> (שניתן להקטינו כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+\\delta_1&lt;x_0\\)</span>)</span></span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,a+\\delta_1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;M=f(x_0)\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha=a+\\frac{\\delta_1}{2}\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;\\alpha&lt;x_0\\)</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\alpha)&gt;f(x_0)\\)</span>.</span></li><li>באופן דומה, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-}f(x)=\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_2&gt;0\\)</span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b-\\delta_2&gt;x_0\\)</span>)</span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(b-\\delta_2,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;M=f(x_0)\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta=b-\\frac{\\delta_2}{2}\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(x_0&lt;\\beta&lt;b\\)</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\beta)&gt;f(x_0)\\)</span>.</span></li></ul>\n<p><em>למה?</em> אנחנו צריכים לעבור לקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span> כדי להפעיל את ויירשטראס, ובניית קצוות שערכי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בהם גדולים ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\)</span></span> מבטיחה שהמינימום &quot;ידחף פנימה&quot; ולא יישאר על הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span>.</span></p>\n<p><strong>שלב 3: קיום מינימום פנימי ומשפט פרמה.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\subset(a,b)\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט 5.37), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[\\alpha,\\beta]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת את המינימום שלה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span>,</span> כלומר לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[\\alpha,\\beta]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>.</span></p>\n<p>בפרט, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\in(\\alpha,\\beta)\\subset[\\alpha,\\beta]\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(c)\\le f(x_0)&lt;f(\\alpha)\\quad\\text{וגם}\\quad f(c)\\le f(x_0)&lt;f(\\beta).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(c\\ne\\alpha\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\ne\\beta\\)</span>,</span></span> ומכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(\\alpha,\\beta)\\subset(a,b)\\)</span></span> היא נקודת מינימום פנימית (ובפרט נקודת מינימום מקומי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>).</span></p>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span>,</span></span> ולכן לפי משפט פרמה (משפט 8.4) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: רציפות של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> ובחירת נקודת השוואה.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> (משפט 7.9). נבחר נקודה כלשהי באמצע הקטע, למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0=\\frac{a+b}{2}\\in(a,b)\\)</span>,</span> ונסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=f(x_0)\\)</span>.</span></p>","<p><strong>שלב 2: חיתוך הקטע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\subset(a,b)\\)</span>.</span></span></strong></p>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> (שניתן להקטינו כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+\\delta_1&lt;x_0\\)</span>)</span></span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,a+\\delta_1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;M=f(x_0)\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha=a+\\frac{\\delta_1}{2}\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;\\alpha&lt;x_0\\)</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\alpha)&gt;f(x_0)\\)</span>.</span></li><li>באופן דומה, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-}f(x)=\\infty\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_2&gt;0\\)</span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b-\\delta_2&gt;x_0\\)</span>)</span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(b-\\delta_2,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;M=f(x_0)\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta=b-\\frac{\\delta_2}{2}\\)</span>.</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(x_0&lt;\\beta&lt;b\\)</span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\beta)&gt;f(x_0)\\)</span>.</span></li></ul>\n<p><em>למה?</em> אנחנו צריכים לעבור לקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span> כדי להפעיל את ויירשטראס, ובניית קצוות שערכי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בהם גדולים ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\)</span></span> מבטיחה שהמינימום &quot;ידחף פנימה&quot; ולא יישאר על הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span>.</span></p>","<p><strong>שלב 3: קיום מינימום פנימי ומשפט פרמה.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\subset(a,b)\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט 5.37), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[\\alpha,\\beta]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת את המינימום שלה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span>,</span> כלומר לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[\\alpha,\\beta]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)\\le f(x)\\)</span>.</span></p>\n<p>בפרט, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\in(\\alpha,\\beta)\\subset[\\alpha,\\beta]\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(c)\\le f(x_0)&lt;f(\\alpha)\\quad\\text{וגם}\\quad f(c)\\le f(x_0)&lt;f(\\beta).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(c\\ne\\alpha\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\ne\\beta\\)</span>,</span></span> ומכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(\\alpha,\\beta)\\subset(a,b)\\)</span></span> היא נקודת מינימום פנימית (ובפרט נקודת מינימום מקומי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>).</span></p>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span>,</span></span> ולכן לפי משפט פרמה (משפט 8.4) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להפעיל ישר את משפט ויירשטראס השני על הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> בלי לצמצם לקטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\alpha,\\beta]\\)</span>.</span></li><li>לשכוח להסביר מדוע נקודת המינימום <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> אינה יכולה ליפול בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span> או בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span> (בלי נקודת ההשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> לא ניתן להפעיל את משפט פרמה, שדורש נקודה פנימית!).</li><li>לנסות להפעיל את משפט רול (משפט 8.5) על <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha,\\beta\\)</span> שרירותיים מבלי לוודא <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(\\alpha)=f(\\beta)\\)</span>.</span></span></li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> (10 נק׳) הוכיחו לפי הגדרת הגבול בלשון <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon, N\\)</span> (הגדרה 2.9) את הגבול:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\frac{8n^2-1}{4n^2-3n}=2.\\]</div>\n<p><strong>ב.</strong> (15 נק׳)</p>\n<p>(1) הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x&lt;\\frac12 x^2\\)</span>.</span></p>\n<p>(2) הוכיחו שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span> למשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x-x^2=a\\)</span> יש פתרון.</p>\n<p>(הסעיפים אינם שווים משקל)</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">צריך להראות שאם רוצים מרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> בין השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8n^2-1}{4n^2-3n}\\)</span> לבין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> פשוט מספיק לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{\\varepsilon}\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: צריך להראות שאם רוצים מרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> בין השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8n^2-1}{4n^2-3n}\\)</span> לבין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> פשוט מספיק לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{\\varepsilon}\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: דמיינו שאנו בודקים כמה השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{8n^2-1}{4n^2-3n}\\)</span> &quot;פספס&quot; את המטרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span> אם מחסרים <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> ועושים מכנה משותף, הפספוס במונה גדל כמו <span class=\"math math-inline\" dir=\"ltr\">\\(6n\\)</span> בזמן שהמכנה גדל כמו <span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span> — לכן הטעות קטנה בסופו של דבר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{n}\\)</span>,</span></span> וככל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> גדול הטעות מתאפסת.</p>\n<p><strong>עם מספרים</strong>: אם מבקשים שהטעות תהיה קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=0.2\\)</span>,</span></span> הנוסחה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{n}&lt;0.2\\)</span> נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;30\\)</span>.</span> נבדוק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=31\\)</span>:</span></span> השבר הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{7687}{3751}\\approx 2.049\\)</span>,</span> והמרחק <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> הוא בערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.049&lt;0.2\\)</span>.</span></p>\n<p><strong>הגדרה בלשון <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon, N\\)</span></strong> היא הבטחה שלכל דיוק <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> שתבקשו, נמצא מספר סף <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> שכל האינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> אחריו כבר מקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L|&lt;\\varepsilon\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול מתאר את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{8x^2-1}{4x^2-3x}\\)</span> שמתקרבת לאסימפטוטה הירוקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=2\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> (רדיוס <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> סביב <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> בין הקווים האדומים) ואת <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ימינה: החל ממקום מסוים כל איברי הסדרה נכנסים לתוך הרצועה סביב <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> ונשארים שם!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:1,&quot;xmax&quot;:26,&quot;ymin&quot;:1.3,&quot;ymax&quot;:3.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;k&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;k=0.3&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.1,&quot;max&quot;:0.8,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=3&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:2,&quot;max&quot;:25,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{8\\\\cdot x^2-1}{4\\\\cdot x^2-3\\\\cdot x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DOTTED&quot;},{&quot;id&quot;:&quot;u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2+k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2-k&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pn&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: עושים מכנה משותף","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: עושים מכנה משותף</p><div class=\"callout-body\"><p>חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{8n^2-1}{4n^2-3n}-2\\right|\\)</span> וצמצמו את האיברים של <span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span> במונה.</p></div></div>"},{"title":"רמז 2: מגדילים מונה ומקטינים מכנה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מגדילים מונה ומקטינים מכנה</p><div class=\"callout-body\"><p>אחרי הצמצום מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6n-1}{4n^2-3n}\\)</span>.</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>,</span> אפשר להחליף את המונה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6n\\)</span>,</span></span> ואת המכנה להקטין — כמה קטן יותר <span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>?</span></p></div></div>"},{"title":"רמז 3: בוחרים $N$ מתכונת ארכימדס","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> מתכונת ארכימדס</p><div class=\"callout-body\"><p>הערכה זו נותנת <span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-2|&lt;\\frac{6}{n}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>.</span> איזה <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> יבטיח שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{n}&lt;\\varepsilon\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפשט את ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-2|\\)</span> לביטוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6n-1}{4n^2-3n}\\)</span>.</span> נראה שמתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\ge n^2\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>,</span> ולכן ההפרש קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6n}{n^2}=\\frac{6}{n}\\)</span>.</span></span> מכאן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> המקיים <span class=\"math math-inline\" dir=\"ltr\">\\(N&gt;\\frac{6}{\\varepsilon}\\)</span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\lfloor\\frac{6}{\\varepsilon}\\rfloor+1\\)</span>),</span> ונסיק <span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-2|&lt;\\varepsilon\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הערכה אלגברית של המרחק <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n=n(4n-3)\\ge 1&gt;0\\)</span>,</span> ולכן כל איברי הסדרה מוגדרים וחיוביים במכנה. בנוסף, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(4n^2-3n)-n^2=3n^2-3n=3n(n-1)\\ge 0,\\]</div>\n<p>כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\ge n^2\\)</span>.</span></p>\n<p><em>למה?</em> הקטנה של המכנה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span></span> מגדילה את השבר כולו ומפשטת אותו למנה פשוטה בלי להצטרך לפתור משוואה ריבועית עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></p>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(6n-1&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n&gt;0\\)</span>,</span> ומכאן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{8n^2-1}{4n^2-3n}-2\\right|=\\left|\\frac{8n^2-1-8n^2+6n}{4n^2-3n}\\right|=\\frac{6n-1}{4n^2-3n}&lt;\\frac{6n}{n^2}=\\frac{6}{n}.\\]</div>\n<p><strong>שלב 2: ההוכחה הפורמלית לפי הגדרה 2.9.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> לפי תכונת ארכימדס (משפט 1.62 / הערך השלם), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(N&gt;\\frac{6}{\\varepsilon}\\)</span></span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\left\\lfloor\\frac{6}{\\varepsilon}\\right\\rfloor+1\\)</span>).</span></p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\frac{6}{\\varepsilon}\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{n}&lt;\\varepsilon\\)</span>.</span> נשתמש באי-השוויון שמצאנו בשלב 1:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{8n^2-1}{4n^2-3n}-2\\right|&lt;\\frac{6}{n}&lt;\\varepsilon.\\]</div>\n<p>לכן לפי הגדרה 2.9 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{8n^2-1}{4n^2-3n}=2\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: הערכה אלגברית של המרחק <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n=n(4n-3)\\ge 1&gt;0\\)</span>,</span> ולכן כל איברי הסדרה מוגדרים וחיוביים במכנה. בנוסף, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(4n^2-3n)-n^2=3n^2-3n=3n(n-1)\\ge 0,\\]</div>\n<p>כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\ge n^2\\)</span>.</span></p>\n<p><em>למה?</em> הקטנה של המכנה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span></span> מגדילה את השבר כולו ומפשטת אותו למנה פשוטה בלי להצטרך לפתור משוואה ריבועית עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></p>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(6n-1&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n&gt;0\\)</span>,</span> ומכאן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{8n^2-1}{4n^2-3n}-2\\right|=\\left|\\frac{8n^2-1-8n^2+6n}{4n^2-3n}\\right|=\\frac{6n-1}{4n^2-3n}&lt;\\frac{6n}{n^2}=\\frac{6}{n}.\\]</div>","<p><strong>שלב 2: ההוכחה הפורמלית לפי הגדרה 2.9.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> לפי תכונת ארכימדס (משפט 1.62 / הערך השלם), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(N&gt;\\frac{6}{\\varepsilon}\\)</span></span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N=\\left\\lfloor\\frac{6}{\\varepsilon}\\right\\rfloor+1\\)</span>).</span></p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\frac{6}{\\varepsilon}\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{6}{n}&lt;\\varepsilon\\)</span>.</span> נשתמש באי-השוויון שמצאנו בשלב 1:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{8n^2-1}{4n^2-3n}-2\\right|&lt;\\frac{6}{n}&lt;\\varepsilon.\\]</div>\n<p>לכן לפי הגדרה 2.9 מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{8n^2-1}{4n^2-3n}=2\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להשתמש באריתמטיקה של גבולות (&quot;נחלק מונה ומכנה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span></span>&quot;): השאלה ביקשה <strong>מפורשות</strong> להוכיח לפי הגדרה 2.9, ואריתמטיקה אינה הוכחה בהגדרה.</li><li>להגדיל מכנה במקום להקטין אותו (למשל להחליף <span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2\\)</span>):</span></span> ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(4n^2-3n\\)</span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4n^2\\)</span>,</span></span> ולכן החלפה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(4n^2\\)</span></span> מקטינה את השבר במקום להגדיל אותו, וזה הולך בכיוון הלא-נכון.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בחלק (1), כשמעבירים אגף רואים פונקציה שמתחילה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ויורדת כל הזמן מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> בחלק (2), תוצאת (1) מבטיחה שהפונקציה צונחת מתחת לכל מספר שלילי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span> והרי היא מתחילה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0&gt;a\\)</span></span> — אז לפי משפט ערך הביניים היא חייבת לפגוע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> בדרך.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בחלק (1), כשמעבירים אגף רואים פונקציה שמתחילה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ויורדת כל הזמן מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> בחלק (2), תוצאת (1) מבטיחה שהפונקציה צונחת מתחת לכל מספר שלילי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span> והרי היא מתחילה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0&gt;a\\)</span></span> — אז לפי משפט ערך הביניים היא חייבת לפגוע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> בדרך.</p>\n<p><strong>תמונה בראש</strong>: צוללת שמתחילה בגובה פני הים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span> ושוקעת מטה. בחלק (1) מראים שהפרבולה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac12 x^2\\)</span> תמיד גבוהה מהגלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x\\)</span>.</span> בחלק (2) מורידים עוד <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac12 x^2\\)</span> למטה (סה&quot;כ מורידים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>),</span> כך שהצוללת יורדת יותר ויותר עמוק ובהכרח חוצה כל עומק שלילי <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span> בדרכה למטה.</p>\n<p><strong>עם מספרים</strong>: לחלק (1) <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\cdot\\cos 1-\\sin 1\\approx 0.54-0.84=-0.30 &lt; 0.5=\\frac12\\cdot 1^2\\)</span>.</span> לחלק (2) אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=-2\\)</span>,</span> אז <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הערך הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&gt;-2\\)</span>,</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=3\\)</span></span> לפי חלק (1) הערך קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12\\cdot 9=-4.5&lt;-2\\)</span>,</span></span> ולכן יש פתרון בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>.</span></span></p>\n<p><strong>משפט לגראנז׳</strong> מקשר בין השינוי הכולל של פונקציה בקטע לבין הנגזרת שלה בנקודת ביניים בתוך הקטע.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>חלק (1): העקומה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\cos x-\\sin x\\)</span> מתחילה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span></span> ונשארת תמיד מתחת לפרבולה האדומה המקווקוות <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\frac12 x^2\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> ימינה והשוו את הנקודה הכחולה לאדומה.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:6,&quot;ymin&quot;:-6,&quot;ymax&quot;:12}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.2,&quot;max&quot;:5,&quot;step&quot;:0.2}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x\\\\cdot\\\\cos(x)-\\\\sin(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{1}{2}\\\\cdot x^2&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pg&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,g(t))&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"},{"title":"רואים את זה בגרף (חלק 2)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (חלק 2)</span></summary><div class=\"callout-body\"><p>חלק (2): העקומה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(p(x)=x\\cos x-\\sin x-x^2\\)</span> מתחילה בנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> ונמצאת תמיד מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12 x^2\\)</span>,</span></span> כך שהיא יורדת ללא סוף. הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span> (הקו האדום המקווקו): הוא תמיד חותך את הגרף הכחול!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:4.5,&quot;ymin&quot;:-14,&quot;ymax&quot;:1.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a=-2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-10,&quot;max&quot;:-0.3,&quot;step&quot;:0.2}},{&quot;id&quot;:&quot;p&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;p(x)=x\\\\cdot\\\\cos(x)-\\\\sin(x)-x^2&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;y&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=a&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: פונקציית הפרש לחלק (1)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: פונקציית הפרש לחלק (1)</p><div class=\"callout-body\"><p>הגדירו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x\\cos x-\\sin x-\\frac12 x^2\\)</span>.</span> חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(h(0)\\)</span> ואת הנגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שימו לב שהנגזרת עלולה להתאפס לרגע!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימו לב שהנגזרת עלולה להתאפס לרגע!</p><div class=\"callout-body\"><p>מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=-x(1+\\sin x)\\le 0\\)</span>.</span> איך מבטיחים אי-שוויון <strong>חזק</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span>)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> אף <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1+\\sin x\\)</span></span> מתאפס <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3\\pi}{2}\\)</span>?</span></span> בדקו מה קורה קודם בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi]\\)</span>!</span></p></div></div>"},{"title":"רמז 3: שימוש בחלק (1) עבור חלק (2)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: שימוש בחלק (1) עבור חלק (2)</p><div class=\"callout-body\"><p>כתבו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x-x^2=\\left(x\\cos x-\\sin x-\\frac12 x^2\\right)-\\frac12 x^2\\)</span>.</span> בעזרת חלק (1), הביטוי קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12 x^2\\)</span>.</span></span> מצאו <span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12 b^2&lt;a\\)</span></span> והפעילו את משפט ערך הביניים (משפט 5.29) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,b]\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>בחלק (1) נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x\\cos x-\\sin x-\\frac12 x^2\\)</span> ונמצא <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=-x(1+\\sin x)\\le 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 0\\)</span>,</span> כאשר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span></span> הנגזרת שלילית ממש; מלגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\min\\{x,\\pi\\}]\\)</span> ואז על <span class=\"math math-inline\" dir=\"ltr\">\\([\\pi,x]\\)</span> נקבל <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> בחלק (2) נציג את אגף שמאל <span class=\"nobr\">כ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)-\\frac12 x^2&lt;-\\frac12 x^2\\)</span>,</span></span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(b=1-a\\)</span> כך שהערך <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> ומערך הביניים על <span class=\"math math-inline\" dir=\"ltr\">\\([0,b]\\)</span> נקבל פתרון.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>(1)</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x)=x\\cos x-\\sin x-\\frac12 x^2.\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה וגזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> נחשב את הנגזרת שלה לפי כלל המכפלה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x)=(\\cos x-x\\sin x)-\\cos x-x=-x\\sin x-x=-x(1+\\sin x).\\]</div>\n<p><em>למה?</em> אם נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> יורדת ממש בהתחלה ולא עולה אחר כך, נקבל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\)</span></span> שלילית ממש לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span></p>\n<p>מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=0\\cdot\\cos 0-\\sin 0-0=0\\)</span>.</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=\\min\\{x,\\pi\\}&gt;0\\)</span>:</span></p>\n<ul><li>בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,m]\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה וגזירה, ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,m)\\subseteq(0,\\pi)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(m)-h(0)=h'(c)\\cdot m=-c(1+\\sin c)m\\)</span>.</span></span> מאחר <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin c&gt;0\\)</span>,</span> כל הגורמים <span class=\"math math-inline\" dir=\"ltr\">\\(c, 1+\\sin c, m\\)</span> חיוביים ממש, ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(m)=-c(1+\\sin c)m&lt;0.\\]</div>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le\\pi\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=x\\)</span>,</span> וכבר קיבלנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\pi\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=\\pi\\)</span>.</span> נפעיל את משפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\pi,x]\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in(\\pi,x)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)-h(\\pi)=h'(d)(x-\\pi)=-d(1+\\sin d)(x-\\pi)\\)</span>.</span></span> מכיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin d\\ge -1\\)</span>,</span> הגורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\sin d\\ge 0\\)</span>,</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(d&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x-\\pi&gt;0\\)</span>.</span></span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)-h(\\pi)\\le 0\\)</span>,</span> ומכאן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x)\\le h(\\pi)&lt;0.\\]</div>\n<p>בשני המקרים <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x&lt;\\frac12 x^2\\)</span>.</span></p>\n<p><strong>(2)</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>.</span> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(x)=x\\cos x-\\sin x-x^2\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (כהרכבה ואריתמטיקה של פונקציות אלמנטריות רציפות).</p>\n<p>בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(0)=0\\cdot\\cos 0-\\sin 0-0^2=0&gt;a.\\]</div>\n<p>כעת נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=1-a\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;1&gt;0\\)</span>,</span> וכן <span class=\"math math-inline\" dir=\"ltr\">\\((1-a)^2=1-2a+a^2&gt;-2a\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+a^2&gt;0\\)</span>),</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12(1-a)^2&lt;a\\)</span>.</span></p>\n<p><em>למה?</em> אנחנו צריכים נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;0\\)</span> שבה הערך של <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> כבר יורד מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> כדי שנוכל לתפוס את <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(p(0)\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(b)\\)</span>.</span></span></p>\n<p>לפי תוצאת סעיף (1), מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\cos b-\\sin b&lt;\\frac12 b^2\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(b)=(b\\cos b-\\sin b)-b^2&lt;\\frac12 b^2-b^2=-\\frac12 b^2=-\\frac12(1-a)^2&lt;a.\\]</div>\n<p>קיבלנו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span></span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,b]\\)</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(b)&lt;a&lt;p(0)\\)</span>.</span> לפי משפט ערך הביניים (משפט 5.29), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,b)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(c)=a\\)</span>,</span></span> כלומר למשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x-x^2=a\\)</span> יש פתרון.</p></div></div>","steps":["<p><strong>(1)</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x)=x\\cos x-\\sin x-\\frac12 x^2.\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה וגזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> נחשב את הנגזרת שלה לפי כלל המכפלה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x)=(\\cos x-x\\sin x)-\\cos x-x=-x\\sin x-x=-x(1+\\sin x).\\]</div>\n<p><em>למה?</em> אם נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> יורדת ממש בהתחלה ולא עולה אחר כך, נקבל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\)</span></span> שלילית ממש לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span></p>\n<p>מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=0\\cdot\\cos 0-\\sin 0-0=0\\)</span>.</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=\\min\\{x,\\pi\\}&gt;0\\)</span>:</span></p>\n<ul><li>בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,m]\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה וגזירה, ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,m)\\subseteq(0,\\pi)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(m)-h(0)=h'(c)\\cdot m=-c(1+\\sin c)m\\)</span>.</span></span> מאחר <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin c&gt;0\\)</span>,</span> כל הגורמים <span class=\"math math-inline\" dir=\"ltr\">\\(c, 1+\\sin c, m\\)</span> חיוביים ממש, ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(m)=-c(1+\\sin c)m&lt;0.\\]</div>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le\\pi\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=x\\)</span>,</span> וכבר קיבלנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;\\pi\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=\\pi\\)</span>.</span> נפעיל את משפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\pi,x]\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in(\\pi,x)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)-h(\\pi)=h'(d)(x-\\pi)=-d(1+\\sin d)(x-\\pi)\\)</span>.</span></span> מכיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin d\\ge -1\\)</span>,</span> הגורם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\sin d\\ge 0\\)</span>,</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(d&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x-\\pi&gt;0\\)</span>.</span></span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)-h(\\pi)\\le 0\\)</span>,</span> ומכאן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x)\\le h(\\pi)&lt;0.\\]</div>\n<p>בשני המקרים <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)&lt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x&lt;\\frac12 x^2\\)</span>.</span></p>\n<p><strong>(2)</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>.</span> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(x)=x\\cos x-\\sin x-x^2\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (כהרכבה ואריתמטיקה של פונקציות אלמנטריות רציפות).</p>\n<p>בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(0)=0\\cdot\\cos 0-\\sin 0-0^2=0&gt;a.\\]</div>\n<p>כעת נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=1-a\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;1&gt;0\\)</span>,</span> וכן <span class=\"math math-inline\" dir=\"ltr\">\\((1-a)^2=1-2a+a^2&gt;-2a\\)</span> (כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+a^2&gt;0\\)</span>),</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac12(1-a)^2&lt;a\\)</span>.</span></p>\n<p><em>למה?</em> אנחנו צריכים נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;0\\)</span> שבה הערך של <span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span> כבר יורד מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>,</span></span> כדי שנוכל לתפוס את <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(p(0)\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(b)\\)</span>.</span></span></p>\n<p>לפי תוצאת סעיף (1), מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b&gt;0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\cos b-\\sin b&lt;\\frac12 b^2\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(b)=(b\\cos b-\\sin b)-b^2&lt;\\frac12 b^2-b^2=-\\frac12 b^2=-\\frac12(1-a)^2&lt;a.\\]</div>\n<p>קיבלנו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(p\\)</span></span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,b]\\)</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(b)&lt;a&lt;p(0)\\)</span>.</span> לפי משפט ערך הביניים (משפט 5.29), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,b)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(c)=a\\)</span>,</span></span> כלומר למשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\cos x-\\sin x-x^2=a\\)</span> יש פתרון.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לכתוב בחלק (1) &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=-x(1+\\sin x)&lt;0\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>&quot; ולהפעיל את משפט 8.18 בלי לשים לב שכאשר <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x=-1\\)</span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{3\\pi}{2}\\)</span>)</span> הנגזרת מתאפסת! עדיף להוציא קודם את הירידה הממשית על <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi]\\)</span> ואחר כך אי-עלייה משם והלאה.</li><li>בחלק (2), לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span> בלי להוכיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(p(b)&lt;a\\)</span></span> (או לבדוק רק שהגבול באינסוף הוא <span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span> בלי להצביע במפורש על משפט ערך הביניים ועל קטע סגור מתאים).</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) — רק למי שלמד/ה את הקורס בסמסטר 2024א/ב/ג</p>\n<p><strong>א.</strong> (10 נק׳) הוכיחו/הפריכו: תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה כך שכמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\infty\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) הוכיחו או הפריכו: הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x-\\arctan x}{x^3}\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">זה שכל איבר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לא אומר שהחזקה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> תעלה לאינסוף — אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מספיק מהר, החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> לא מספיקה לנפח אותו.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: זה שכל איבר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לא אומר שהחזקה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> תעלה לאינסוף — אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מספיק מהר, החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> לא מספיקה לנפח אותו.</p>\n<p><strong>תמונה בראש</strong>: דמיינו ריבית של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> למשך <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ימים. התנאי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span> (לחיוביים) רק אומר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>,</span></span> כלומר יש רווח קטן כלשהו. אבל אם הבנק מקטין את שיעור הריבית בדיוק בהתאמה למספר הימים — כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> הימים תמיד נותנים סכום קבוע — הכסף נשאר תקוע במקום ולא גדל לאינסוף!</p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>.</span> תמיד <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1&gt;0\\)</span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=2\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_2=\\sqrt{2}\\approx 1.41\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{10}\\approx 1.072\\)</span>),</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>.</span> אבל כשמעלים בחזקת <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מקבלים תמיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((2^{\\frac1n})^n=2\\)</span>,</span> שאינה שואפת לאינסוף אלא <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>!</span></span> (דוגמה נוספת: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span>,</span> ואז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1+\\frac1n)^n\\to e&lt;\\infty\\)</span>.)</span></p>\n<p><strong>כמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></strong> פירושו &quot;לכל האינדקסים החל ממקום מסוים (פרט אולי למספר סופי של איברים בהתחלה)&quot;.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה מציגה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>,</span> שנשארת תמיד מעל הקו האפור <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> (ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>).</span> אבל העקומה האדומה של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> שווה תמיד <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> ואינה עולה לאינסוף! הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> קדימה וראו את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> יורדת לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span></span> נשארת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.2,&quot;xmax&quot;:12.5,&quot;ymin&quot;:0.4,&quot;ymax&quot;:2.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:12,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=2^{\\\\frac{1}{x}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pp&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: תרגמו את התנאי על $a_n$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: תרגמו את התנאי על <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></p><div class=\"callout-body\"><p>כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span> אפשר לחלק את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>:</span></span> מתקבל פשוט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>.</span></p></div></div>"},{"title":"רמז 2: חשבו על צורות אי-ודאות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: חשבו על צורות אי-ודאות</p><div class=\"callout-body\"><p>אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 1\\)</span>,</span> אז הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> הוא מהצורה <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> — ואפשר לקבל ממנו גם גבול סופי!</p></div></div>"},{"title":"רמז 3: דוגמה מפורשת","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: דוגמה מפורשת</p><div class=\"callout-body\"><p>בחרו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span></span> יהיה קל מאוד לחישוב, למשל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{1/n}\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span>).</span> בדקו את כל התנאים.</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>הטענה לא נכונה. התנאים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span></span> שקולים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>,</span></span> אך אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 1^+\\)</span> מהר מספיק, החזקה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> אינה שואפת לאינסוף. ניקח כדוגמה נגדית את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>:</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>,</span> אך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=2\\to 2\\ne\\infty\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: בניית הדוגמה הנגדית.</strong> נגדיר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=2^{\\frac1n}.\\]</div>\n<p><strong>שלב 2: בדיקת התנאים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}&gt;2^0=1&gt;0\\)</span> (מאחר שהפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(2^t\\)</span> עולה ממש וחיובית).</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span></span> כפל אי-השוויון <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> בגורם החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n^2&gt;a_n\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> (ובפרט כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>).</span></p>\n<p><em>למה?</em> במקום להסתמך על <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> שנותן גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span> הבחירה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> מבטלת את החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מיד ונותנת מספר קבוע בלי שום חישוב מסובך.</p>\n<p><strong>שלב 3: הפרכת המסקנה.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(a_n)^n=\\left(2^{\\frac1n}\\right)^n=2^1=2.\\]</div>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}2=2\\ne\\infty\\)</span>.</span></p></div></div>","steps":["<p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: בניית הדוגמה הנגדית.</strong> נגדיר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=2^{\\frac1n}.\\]</div>","<p><strong>שלב 2: בדיקת התנאים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}&gt;2^0=1&gt;0\\)</span> (מאחר שהפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(2^t\\)</span> עולה ממש וחיובית).</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span></span> כפל אי-השוויון <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> בגורם החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n^2&gt;a_n\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> (ובפרט כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>).</span></p>\n<p><em>למה?</em> במקום להסתמך על <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1+\\frac1n\\)</span> שנותן גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span> הבחירה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> מבטלת את החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מיד ונותנת מספר קבוע בלי שום חישוב מסובך.</p>","<p><strong>שלב 3: הפרכת המסקנה.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(a_n)^n=\\left(2^{\\frac1n}\\right)^n=2^1=2.\\]</div>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\lim_{n\\to\\infty}2=2\\ne\\infty\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לטעון שמכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>,</span></span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\to\\infty\\)</span>:</span> זה נכון רק עבור <strong>בסיס קבוע</strong> <span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;1\\)</span> (או בסיסים המרוחקים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge c&gt;1\\)</span>),</span> ולא <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> מתקרב אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></li><li>לבחור סדרה שלילית או סדרה כמו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1\\)</span> (שם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2=a_n\\)</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>!).</span> צריך לבדוק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span></span> מתקיים ממש.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> המונה <span class=\"math math-inline\" dir=\"ltr\">\\(x-\\arctan x\\)</span> מצטמצם יפה מול <span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span> ומשאיר את הפונקציה ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span>,</span> ובצד הימני היא נמחצת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{x^2}\\)</span></span> — ולכן היא חסומה לכל אורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> המונה <span class=\"math math-inline\" dir=\"ltr\">\\(x-\\arctan x\\)</span> מצטמצם יפה מול <span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span> ומשאיר את הפונקציה ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span>,</span> ובצד הימני היא נמחצת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{x^2}\\)</span></span> — ולכן היא חסומה לכל אורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: נבדוק את הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> בשני חצאים. בחצי השמאלי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>,</span> שבר בצורת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac00\\)</span> עלול להתפוצץ או להירגע — כלל לופיטל מגלה שהוא נרגע בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span>,</span> כך שאפשר לסגור את הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולהפעיל את ויירשטראס. בחצי הימני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>,</span> הזווית <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> לעולם לא עוברת את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}&lt;2\\)</span>,</span> כך שהמכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span> מנצח את המונה ומוחץ את הגרף לאפס.</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0.1-\\arctan 0.1}{0.001}\\approx 0.331\\approx\\frac13\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1-\\pi/4}{1}\\approx 0.215\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{|10-\\arctan 10|}{1000}\\le\\frac{12}{1000}=0.012\\)</span>.</span></p>\n<p><strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></strong> היא הזווית (ברדיאנים, בין <span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{\\pi}{2}\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}\\)</span>)</span></span> שהטנגנס שלה שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span></span> ונגזרתה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1+x^2}\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x-\\arctan x}{x^3}\\)</span> מתקרבת משמאל לקו <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> אל החור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac13)\\)</span>,</span> ומימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> יורדת ונשארת מתחת לעקומת החסם האדומה המקווקוות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=\\frac{3}{x^2}\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לעקוב אחרי הערכים.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:5.5,&quot;ymin&quot;:-0.05,&quot;ymax&quot;:0.7}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.5&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:5,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{x-\\\\arctan(x)}{x^3}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\frac{3}{x^2}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0.3333)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, 1/3)&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מפצלים את הקטע","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מפצלים את הקטע</p><div class=\"callout-body\"><p>הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> אינו סגור ואינו חסום. פצלו אותו <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> <span class=\"nobr\">ול-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></p></div></div>"},{"title":"רמז 2: מה קורה ב-$x\\to 0^+$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מה קורה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span></p><div class=\"callout-body\"><p>הפעילו את כלל לופיטל (משפט 8.13) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x-\\arctan x}{x^3}\\)</span>.</span> אל תשכחו לפשט אלגברית את <span class=\"math math-inline\" dir=\"ltr\">\\(1-\\frac{1}{1+x^2}\\)</span> — הפעם גזירה אחת בלבד מספיקה!</p></div></div>"},{"title":"רמז 3: חסימות על $[1,\\infty)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: חסימות על <span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></p><div class=\"callout-body\"><p>השתמשו בכך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}&lt;2\\)</span>:</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-\\arctan x|\\le x+2\\le 3x\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפצל את <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> <span class=\"nobr\">ול-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span> בעזרת גזירה אחת של כלל לופיטל וצמצום אלגברי נראה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=\\frac13\\)</span>,</span></span> נשלים את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ונסיק ממשפט ויירשטראס הראשון שהיא חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> נחסום ישירות <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le\\frac{3}{x^2}\\le 3\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span>.</span></span></strong> הפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x-\\arctan x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span></span> גזירות ורציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (לפי משפט 7.28, הנובע ממשפט 7.27, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan x)'=\\frac{1}{1+x^2}\\)</span>),</span> שתיהן שואפות <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan 0=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span></span> רציפה לפי משפט 5.43), ונגזרת המכנה <span class=\"math math-inline\" dir=\"ltr\">\\((x^3)'=3x^2\\ne 0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p>נחשב את גבול מנת הנגזרות: לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{(x-\\arctan x)'}{(x^3)'}=\\frac{1-\\frac{1}{1+x^2}}{3x^2}=\\frac{\\frac{x^2}{1+x^2}}{3x^2}=\\frac{1}{3(1+x^2)}\\xrightarrow[x\\to 0^+]{}\\frac{1}{3(1+0)}=\\frac13.\\]</div>\n<p>לפי כלל לופיטל (משפט 8.13 בגרסה החד-צדדית), קיים הגבול:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{x-\\arctan x}{x^3}=\\frac13.\\]</div>\n<p><em>למה?</em> לאחר גזירה אחת המונה הפך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x^2}{1+x^2}\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> הצטמצם מיד מול <span class=\"math math-inline\" dir=\"ltr\">\\(3x^2\\)</span> שבמכנה בלי צורך לגזור שוב.</p>\n<p><strong>שלב 2: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,1]\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=\\frac13\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> (מנה של רציפות עם מכנה שונה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> ורציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}h(x)=\\frac13=h(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ולפי המשפט הראשון של ויירשטראס (משפט 5.35) היא חסומה בו: קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_1\\)</span>.</span></p>\n<p><strong>שלב 3: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></strong> מהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> (הגדרה 5.45), <span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}&lt;2\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> מכאן שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x-\\arctan x|\\le |x|+|\\arctan x|&lt;x+2\\le x+2x=3x.\\]</div>\n<p>ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)|=\\frac{|x-\\arctan x|}{x^3}\\le\\frac{3x}{x^3}=\\frac{3}{x^2}\\le 3.\\]</div>\n<p><strong>שלב 4: סיכום.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\max\\{M_1,3\\}\\)</span>.</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","steps":["<p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span>.</span></span></strong> הפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x-\\arctan x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span></span> גזירות ורציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (לפי משפט 7.28, הנובע ממשפט 7.27, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan x)'=\\frac{1}{1+x^2}\\)</span>),</span> שתיהן שואפות <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan 0=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span></span> רציפה לפי משפט 5.43), ונגזרת המכנה <span class=\"math math-inline\" dir=\"ltr\">\\((x^3)'=3x^2\\ne 0\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p>נחשב את גבול מנת הנגזרות: לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{(x-\\arctan x)'}{(x^3)'}=\\frac{1-\\frac{1}{1+x^2}}{3x^2}=\\frac{\\frac{x^2}{1+x^2}}{3x^2}=\\frac{1}{3(1+x^2)}\\xrightarrow[x\\to 0^+]{}\\frac{1}{3(1+0)}=\\frac13.\\]</div>\n<p>לפי כלל לופיטל (משפט 8.13 בגרסה החד-צדדית), קיים הגבול:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{x-\\arctan x}{x^3}=\\frac13.\\]</div>\n<p><em>למה?</em> לאחר גזירה אחת המונה הפך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x^2}{1+x^2}\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> הצטמצם מיד מול <span class=\"math math-inline\" dir=\"ltr\">\\(3x^2\\)</span> שבמכנה בלי צורך לגזור שוב.</p>","<p><strong>שלב 2: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>.</span></span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,1]\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=\\frac13\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span></span> (מנה של רציפות עם מכנה שונה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> ורציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}h(x)=\\frac13=h(0)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ולפי המשפט הראשון של ויירשטראס (משפט 5.35) היא חסומה בו: קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_1\\)</span>.</span></p>","<p><strong>שלב 3: חסימות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></strong> מהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> (הגדרה 5.45), <span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}&lt;2\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> מכאן שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x-\\arctan x|\\le |x|+|\\arctan x|&lt;x+2\\le x+2x=3x.\\]</div>\n<p>ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)|=\\frac{|x-\\arctan x|}{x^3}\\le\\frac{3x}{x^3}=\\frac{3}{x^2}\\le 3.\\]</div>","<p><strong>שלב 4: סיכום.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\max\\{M_1,3\\}\\)</span>.</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח לבדוק גבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> או להסתפק בגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> בלי להשלים לקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> ולהפעיל את ויירשטראס הראשון.</li><li>לחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan x)'=\\frac{1}{\\sqrt{1-x^2}}\\)</span></span> (זו הנגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1+x^2}\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) — רק למי שלמד/ה את הקורס בסמסטר אחר (שנה 2023 או סמסטר 2025א)</p>\n<p><strong>א.</strong> (10 נק׳) הוכיחו/הפריכו: תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה כך שכמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(a_n)^n=\\infty\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) הוכיחו או הפריכו: הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x-\\arctan x}{x^3}\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">גם אם כל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> אם הוא מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מספיק מהר החזקה <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ית לא חייבת לברוח לאינסוף.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: גם אם כל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> אם הוא מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מספיק מהר החזקה <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ית לא חייבת לברוח לאינסוף.</p>\n<p><strong>תמונה בראש</strong>: נניח שבכל שנה הכסף גדל בפי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>,</span> אבל ככל שמספר השנים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> גדול יותר, המכפיל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מתכווץ קרוב <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> אם המכפיל מתאים בדיוק לשורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> המכפלה בסוף <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שנים תישאר תמיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1&gt;0\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span>.</span> אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=(2^{\\frac1n})^n=2\\to 2\\ne\\infty\\)</span>.</span></p>\n<p><strong>כמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></strong> פירושו שלכל <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-ים החל מאיזשהו <span class=\"math math-inline\" dir=\"ltr\">\\(N_0\\)</span> והלאה התנאי מתקיים.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> שנשארת מעל הקו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>,</span> אבל החזקה האדומה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> שווה תמיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> קדימה וראו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span></span> נשארת תקועה על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.2,&quot;xmax&quot;:12.5,&quot;ymin&quot;:0.4,&quot;ymax&quot;:2.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:12,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=2^{\\\\frac{1}{x}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pp&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: פירוש התנאים על $a_n$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: פירוש התנאים על <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></p><div class=\"callout-body\"><p><span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> <span class=\"nobr\">ומ-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span></span> מקבלים פשוט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>.</span></p></div></div>"},{"title":"רמז 2: דוגמה נגדית שבה $(a_n)^n$ קבועה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמה נגדית שבה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span> קבועה</p><div class=\"callout-body\"><p>חשבו על בחירה של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span></span> יהיה קבוע (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>)</span> או בעל גבול סופי (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>).</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>הטענה לא נכונה. התנאים שקולים לכך שכמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span>,</span> אך אם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 1^+\\)</span> אפשר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n\\)</span></span> יתכנס לגבול סופי. ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> ונבדוק שכל התנאים מתקיימים בעוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=2\\to 2\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: דוגמה נגדית.</strong> נבחר את הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span></p>\n<p><strong>שלב 2: בדיקת התנאים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}&gt;2^0=1&gt;0\\)</span>.</span> בכפל של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> במספר החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מתקבל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span></p>\n<p><em>למה?</em> הדוגמה הזאת מקיימת את התנאים אפילו לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> ולא רק כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> והיא נוחה כי החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מבטלת את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span> מיד.</p>\n<p><strong>שלב 3: חישוב הגבול.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=\\left(2^{\\frac1n}\\right)^n=2\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(a_n)^n=2\\ne\\infty.\\]</div></div></div>","steps":["<p><strong>התשובה: לא נכון</strong></p>\n<p><strong>שלב 1: דוגמה נגדית.</strong> נבחר את הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span></p>","<p><strong>שלב 2: בדיקת התנאים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{\\frac1n}&gt;2^0=1&gt;0\\)</span>.</span> בכפל של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span> במספר החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מתקבל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span></p>\n<p><em>למה?</em> הדוגמה הזאת מקיימת את התנאים אפילו לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> ולא רק כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> והיא נוחה כי החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מבטלת את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac1n\\)</span> מיד.</p>","<p><strong>שלב 3: חישוב הגבול.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)^n=\\left(2^{\\frac1n}\\right)^n=2\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(a_n)^n=2\\ne\\infty.\\]</div>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להניח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;1\\)</span></span> גורר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^n\\to\\infty\\)</span> כמו בסדרה הנדסית עם בסיס קבוע.</li><li>לשכוח לבדוק בדוגמה הנגדית <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2&gt;a_n\\)</span> (למשל להציע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=1\\)</span>,</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(1^2=1\\)</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^2&gt;1\\)</span>).</span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הפונקציה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> מתייצבת לגבול סופי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> ונרגעת לגבול סופי <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> באינסוף — ולכן היא רגועה מספיק כדי להיות רציפה במידה שווה בכל הקטע.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הפונקציה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> מתייצבת לגבול סופי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> ונרגעת לגבול סופי <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> באינסוף — ולכן היא רגועה מספיק כדי להיות רציפה במידה שווה בכל הקטע.</p>\n<p><strong>תמונה בראש</strong>: רציפות במידה שווה נכשלת רק אם יש איפשהו קפיצה חדה, נסיקה לאינסוף, או התנודדות מהירה יותר ויותר. כאן, מצד שמאל ליד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> הגרף נכנס יפה לחור <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac13)\\)</span> ואין קפיצה, ומצד ימין בדרך לאינסוף הגרף שוקע ונצמד אל האסימפטוטה האופקית <span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span> — כך שממקום מסוים הגובה בקושי זז, והחלק הנותר הוא קטע סגור שבו משפט קנטור דואג למרחק אחיד.</p>\n<p><strong>עם מספרים</strong>: אם נתבקש שההפרש בגובה יהיה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=0.02\\)</span>:</span></span> מאזור <span class=\"math math-inline\" dir=\"ltr\">\\(x=15\\)</span> והלאה הגובה כבר מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.008\\)</span>,</span></span> כך שכל שתי נקודות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(15\\)</span></span> והלאה רחוקות בגובה בפחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.016&lt;0.02\\)</span>.</span></span> ועל <span class=\"math math-inline\" dir=\"ltr\">\\([0,16]\\)</span> הפונקציה רציפה בקטע סגור ולכן במ״ש לפי קנטור.</p>\n<p><strong>משפט קנטור</strong> קובע שכל פונקציה רציפה בקטע סגור וחסום היא גם רציפה בו במידה שווה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה מתקרבת לחור <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac13)\\)</span> משמאל ונרגעת אל הקו האדום המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span> מימין. הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לבדוק שאין שום מקום שבו הגרף נעשה תלול עד אינסוף או מתנודד במהירות גדלה.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:7,&quot;ymin&quot;:-0.04,&quot;ymax&quot;:0.45}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=1&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:6.5,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{x-\\\\arctan(x)}{x^3}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;a0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0.3333)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, 1/3)&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: בדיקת שני הקצוות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: בדיקת שני הקצוות</p><div class=\"callout-body\"><p>חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)\\)</span> בעזרת כלל לופיטל, ואת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)\\)</span> בעזרת החסם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}\\)</span>.</span></p></div></div>"},{"title":"רמז 2: השלמה לקרן $[0,\\infty)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: השלמה לקרן <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></p><div class=\"callout-body\"><p>הגדירו <span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=\\frac13\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> כעת <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ובעלת גבול סופי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> (תבנית שאלה 48 ביחידה 5).</p></div></div>"},{"title":"רמז 3: הוכחה מלאה דרך קנטור וחפיפה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: הוכחה מלאה דרך קנטור וחפיפה</p><div class=\"callout-body\"><p>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> מצאו <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> שמשם <span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span> (ומכאן <span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>).</span> הפעילו את קנטור (משפט 5.48) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> וקחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נחשב את הגבול מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac13\\)</span>,</span> לפי כלל לופיטל) ונשלים את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לפונקציה רציפה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span> נראה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>,</span></span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> נפצל לחפיפה של <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> (שם קנטור נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1\\)</span>)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span> (שם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span>).</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: השלמה ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></span></strong> כפי שחושב בכלל לופיטל (משפט 8.13 בגרסה החד-צדדית),</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{x-\\arctan x}{x^3}=\\lim_{x\\to 0^+}\\frac{1-\\frac{1}{1+x^2}}{3x^2}=\\lim_{x\\to 0^+}\\frac{1}{3(1+x^2)}=\\frac13.\\]</div>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=\\frac13\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p>בנוסף, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le |h(x)|=\\frac{|x-\\arctan x|}{x^3}\\le\\frac{x+\\frac{\\pi}{2}}{x^3}=\\frac{1}{x^2}+\\frac{\\pi}{2x^3}\\xrightarrow[x\\to\\infty]{}0.\\]</div>\n<p>לפי משפט הסנדוויץ׳ לפונקציות, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>.</span></p>\n<p><strong>שלב 2: טיפול בזנב <span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span> ובקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> (מסקנת שאלה 48 ביחידה 5).</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|h(x)-h(y)|\\le|h(x)|+|h(y)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>על הקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה ולכן לפי משפט קנטור (משפט 5.48) היא רציפה בו במידה שווה: קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> המקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span>.</span></p>\n<p><strong>שלב 3: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}&gt;0\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>,</span> ובלי הגבלת הכלליות נניח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le K\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y&lt;x+\\delta\\le K+1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span>,</span> ומקנטור נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span>,</span> אז גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\ge x&gt;K\\)</span>,</span> ולכן מהערכת הזנב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> החפיפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([K,K+1]\\)</span> ברוחב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> דואגת שלא ייווצר זוג נקודות במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\le 1\\)</span></span> שקופץ משמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(K\\)</span></span> אל מעבר <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(K+1\\)</span>.</span></span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הגדרה 5.46.</p></div></div>","steps":["<p><strong>התשובה: נכון</strong></p>\n<p><strong>שלב 1: השלמה ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></span></strong> כפי שחושב בכלל לופיטל (משפט 8.13 בגרסה החד-צדדית),</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}\\frac{x-\\arctan x}{x^3}=\\lim_{x\\to 0^+}\\frac{1-\\frac{1}{1+x^2}}{3x^2}=\\lim_{x\\to 0^+}\\frac{1}{3(1+x^2)}=\\frac13.\\]</div>\n<p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h:[0,\\infty)\\to\\mathbb R\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(0)=\\frac13\\)</span>.</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p>בנוסף, מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\arctan x|&lt;\\frac{\\pi}{2}\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le |h(x)|=\\frac{|x-\\arctan x|}{x^3}\\le\\frac{x+\\frac{\\pi}{2}}{x^3}=\\frac{1}{x^2}+\\frac{\\pi}{2x^3}\\xrightarrow[x\\to\\infty]{}0.\\]</div>\n<p>לפי משפט הסנדוויץ׳ לפונקציות, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>.</span></p>","<p><strong>שלב 2: טיפול בזנב <span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span> ובקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span> (מסקנת שאלה 48 ביחידה 5).</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}h(x)=0\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K&gt;1\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span> לכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\ge K\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|h(x)-h(y)|\\le|h(x)|+|h(y)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>על הקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,K+1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה ולכן לפי משפט קנטור (משפט 5.48) היא רציפה בו במידה שווה: קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> המקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|h(x)-h(y)|&lt;\\varepsilon\\)</span>.</span></p>","<p><strong>שלב 3: בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\{1,\\delta_1\\}&gt;0\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span>,</span> ובלי הגבלת הכלליות נניח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le K\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y&lt;x+\\delta\\le K+1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,K+1]\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span>,</span> ומקנטור נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;K\\)</span>,</span> אז גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\ge x&gt;K\\)</span>,</span> ולכן מהערכת הזנב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> החפיפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([K,K+1]\\)</span> ברוחב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> דואגת שלא ייווצר זוג נקודות במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\le 1\\)</span></span> שקופץ משמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(K\\)</span></span> אל מעבר <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(K+1\\)</span>.</span></span></p>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הגדרה 5.46.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להניח שאם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה וחסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> אז היא אוטומטית רציפה במ״ש (זה לא נכון, למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)\\)</span>).</span></li><li>לשכוח לבדוק גבול סופי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0^+\\)</span></span> או לחבר שני קטעים <span class=\"math math-inline\" dir=\"ltr\">\\([0,K]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([K,\\infty)\\)</span></span> בלי חפיפה ביניהם.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>נאמר שקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <strong>צפופה</strong> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span> אם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span></p>\n<ol><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(A,B\\)</span> צפופות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span></li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(A,B\\)</span> צפופות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שתי קבוצות צפופות יכולות לחמוק זו מזו לחלוטין כך שהחיתוך שלהן ריק, אבל האיחוד שלהן גדול יותר מכל אחת מהן ולכן נשאר צפוף.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שתי קבוצות צפופות יכולות לחמוק זו מזו לחלוטין כך שהחיתוך שלהן ריק, אבל האיחוד שלהן גדול יותר מכל אחת מהן ולכן נשאר צפוף.</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש ארוך שבו יש פסי חניה אדומים צפופים בכל מטר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> הרציונליים), וביניהם פסי חניה כחולים שגם הם צפופים בכל מטר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span>,</span> האי-רציונליים). אף נקודה אינה גם אדומה וגם כחולה, ולכן החיתוך שלהם ריק לגמרי! אבל אם מאחדים את כל הפסים יחד, בכל קטע עדיין יש שפע של מקומות.</p>\n<p><strong>עם מספרים</strong>: בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=\\mathbb R\\)</span>,</span> קבוצת הרציונליים <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.25\\)</span>)</span> צפופה, וגם קבוצת האי-רציונליים <span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sqrt{2}}{4}\\approx 0.3536\\)</span>)</span> צפופה. אבל החיתוך <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\emptyset\\)</span> ריק לגמרי!</p>\n<p><strong>חיתוך <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B\\)</span></strong> מכיל רק איברים שנמצאים גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> וגם <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span>;</span></span> <strong>איחוד <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span></strong> מכיל איברים שנמצאים לפחות באחת מהן.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בתוך הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,1)\\)</span>,</span> בכל פתח כמו <span class=\"math math-inline\" dir=\"ltr\">\\((0.2,0.5)\\)</span> בין הקווים המקווקווים האדומים יש גם רציונלי כחול <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0.25\\in\\mathbb Q\\)</span>)</span> וגם אי-רציונלי ירוק <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sqrt{2}}{4}\\notin\\mathbb Q\\)</span>).</span> שתי הקבוצות צפופות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span></span> אך הן זרות לחלוטין והחיתוך שלהן ריק!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.1,&quot;ymin&quot;:-0.6,&quot;ymax&quot;:0.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;i0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;i1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0.2&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0.5&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pq&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.25,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;0.25 in Q&quot;},{&quot;id&quot;:&quot;pi&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.3536,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;sqrt(2)/4 not in Q&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זוג צפופות מפורסמות ב-$\\mathbb R$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זוג צפופות מפורסמות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></p><div class=\"callout-body\"><p>האם יש שתי קבוצות זרות שכל אחת מהן צפופה בכל קטע? חשבו על המספרים הרציונליים ועל המשלימה שלהם.</p></div></div>"},{"title":"רמז 2: טענה 2 פשוטה הרבה יותר","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: טענה 2 פשוטה הרבה יותר</p><div class=\"callout-body\"><p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\subseteq A\\cup B\\)</span>,</span></span> כל איבר של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> שכבר מצאתם בין <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span> נמצא אוטומטית גם <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את טענה 1 בעזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=\\mathbb R\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>:</span></span> שתיהן צפופות (צפיפות הרציונליים והאי-רציונליים) אך החיתוך שלהן ריק. נוכיח את טענה 2 ישירות מהעובדה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\subseteq A\\cup B\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: לא נכונה.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=\\mathbb R\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>.</span></span></p>\n<ul><li>לפי משפט 1.66, <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></li><li>גם <span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>:</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> קיים לפי משפט 1.66 מספר רציונלי <span class=\"math math-inline\" dir=\"ltr\">\\(q\\in\\mathbb Q\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x-\\sqrt{2}&lt;q&lt;y-\\sqrt{2}\\)</span>,</span></span> ואז <span class=\"math math-inline\" dir=\"ltr\">\\(b=q+\\sqrt{2}\\)</span> מקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;y\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(b\\notin\\mathbb Q\\)</span> (אילו היה רציונלי, אז <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}=b-q\\)</span> היה רציונלי, בסתירה לכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}\\)</span></span> אי-רציונלי).</li></ul>\n<p>אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\mathbb Q\\cap(\\mathbb R\\setminus\\mathbb Q)=\\emptyset\\)</span>,</span> והקבוצה הריקה אינה צפופה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (אין אף איבר בה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span></span></p>\n<p><em>למה?</em> הצפיפות דורשת נקודות בכל קטע פתוח, אבל שתי קבוצות צפופות יכולות לדלג זו על הנקודות של זו ולא לחלוק אף נקודה משותפת.</p>\n<p><strong>טענה 2: נכונה.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\subseteq A\\cup B\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\cup B\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span> (אפילו לא הזדקקנו לכך שגם <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> צפופה — מספיק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה.)</p>\n<p><strong>התשובה במבחן</strong>: טענה 2 בלבד נכונה (תשובה <strong>ב</strong>).</p></div></div>","steps":["<p><strong>טענה 1: לא נכונה.</strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=\\mathbb R\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span>.</span></span></p>\n<ul><li>לפי משפט 1.66, <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\mathbb Q\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></li><li>גם <span class=\"math math-inline\" dir=\"ltr\">\\(B=\\mathbb R\\setminus\\mathbb Q\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>:</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> קיים לפי משפט 1.66 מספר רציונלי <span class=\"math math-inline\" dir=\"ltr\">\\(q\\in\\mathbb Q\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x-\\sqrt{2}&lt;q&lt;y-\\sqrt{2}\\)</span>,</span></span> ואז <span class=\"math math-inline\" dir=\"ltr\">\\(b=q+\\sqrt{2}\\)</span> מקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;b&lt;y\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(b\\notin\\mathbb Q\\)</span> (אילו היה רציונלי, אז <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}=b-q\\)</span> היה רציונלי, בסתירה לכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{2}\\)</span></span> אי-רציונלי).</li></ul>\n<p>אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\cap B=\\mathbb Q\\cap(\\mathbb R\\setminus\\mathbb Q)=\\emptyset\\)</span>,</span> והקבוצה הריקה אינה צפופה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (אין אף איבר בה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span></span></p>\n<p><em>למה?</em> הצפיפות דורשת נקודות בכל קטע פתוח, אבל שתי קבוצות צפופות יכולות לדלג זו על הנקודות של זו ולא לחלוק אף נקודה משותפת.</p>","<p><strong>טענה 2: נכונה.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in I\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;a&lt;y\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\subseteq A\\cup B\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\in A\\cup B\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\cup B\\)</span> צפופה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span> (אפילו לא הזדקקנו לכך שגם <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> צפופה — מספיק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> צפופה.)</p>\n<p><strong>התשובה במבחן</strong>: טענה 2 בלבד נכונה (תשובה <strong>ב</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להתבלבל בין חיתוך של קבוצות פתוחות וצפופות (שבמקרים מתקדמים נשאר צפוף) לבין חיתוך של קבוצות צפופות כלליות כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb Q\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\setminus\\mathbb Q\\)</span>.</span></span></li><li>לקחת כדוגמה נגדית לטענה 1 שתי קבוצות סופיות כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\{1\\}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\{2\\}\\)</span></span> — שהן בכלל לא צפופות ולא מקיימות את הנתון!</li></ul></div></div>"}],"similar":"","mc":{"1":false,"2":true}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x),g(x)\\)</span> פונקציות חסומות מלרע בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>.</span></p>\n<ol><li><span class=\"math math-inline\" dir=\"ltr\">\\(c\\cdot f(x)\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-g(x)\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\cdot g(x)\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 3 ד. 1,2 ה. 1,3 ו. 2,3 ז. 1,2,3 ח. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">&quot;חסומה מלרע&quot; רק אומר שיש רצפה מתחת לפונקציה, לא שיש תקרה מעליה — ולכן כל סימן מינוס (בשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>,</span> בחיסור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-g\\)</span>,</span> או בכפל במספר שלילי כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span> הופך את ההמראה למעלה לצניחה אינסופית למטה!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: &quot;חסומה מלרע&quot; רק אומר שיש רצפה מתחת לפונקציה, לא שיש תקרה מעליה — ולכן כל סימן מינוס (בשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>,</span> בחיסור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-g\\)</span>,</span> או בכפל במספר שלילי כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span> הופך את ההמראה למעלה לצניחה אינסופית למטה!</p>\n<p><strong>תמונה בראש</strong>: דמיינו שני טילים שיושבים מעל הרצפה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=-1\\)</span>,</span> כך שאסור להם לרדת מהמרתף, אבל הם יכולים להמריא לחלל <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(+∞\\)</span>)</span> כמה שירצו. בטענה 1 הופכים את כיוון הטיל במראה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>),</span> אז הוא נופל לתהום. בטענה 2 מחסרים טיל שממריא לחלל <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ומקבלים צניחה לתהום. בטענה 3 כופלים את הטיל שממריא לחלל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> (שחסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> ושוב מקבלים צניחה לתהום!</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span></span> נסתכל על <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x&gt;0\\)</span> (חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\((-1)\\cdot x=-x\\)</span> (טענה 1), <span class=\"math math-inline\" dir=\"ltr\">\\(0-x=-x\\)</span> (טענה 2), <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((-1)\\cdot x=-x\\)</span></span> (טענה 3) — כולן נותנות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-x\\)</span>,</span> <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1000\\)</span></span> היא <span class=\"math math-inline\" dir=\"ltr\">\\(-1000\\)</span> והולכת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>!</span></span></p>\n<p><strong>חסומה מלרע</strong> פירושו שקיים מספר <span class=\"math math-inline\" dir=\"ltr\">\\(m\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge m\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> על <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> (נשאר תמיד מעל הקו האפור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>,</span> ולכן חסום מלרע), והקו הירוק הוא <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=-1\\)</span> (חסום מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>).</span> הקו האדום <span class=\"math math-inline\" dir=\"ltr\">\\(y=c\\cdot f(x)\\)</span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>)</span> ממריא למטה בלי שום רצפה! הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי לראות כיצד כל אחד משלושת הביטויים בורח <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:4.2,&quot;ymin&quot;:-8,&quot;ymax&quot;:5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;c&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;c=-1&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-2,&quot;max&quot;:-0.2,&quot;step&quot;:0.2}},{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.5,&quot;max&quot;:3.5,&quot;step&quot;:0.25}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;h&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-1&quot;,&quot;color&quot;:&quot;#388c46&quot;},{&quot;id&quot;:&quot;cf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=c\\\\cdot f(x)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;w&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;z&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;pcf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,c\\\\cdot f(t))&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זכרו ש-\"חסומה מלרע\" מרשה להגיע ל-$+\\infty$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זכרו ש-&quot;חסומה מלרע&quot; מרשה להגיע <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span></p><div class=\"callout-body\"><p>פונקציה כמו <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> היא חסומה מלרע! מה קורה לה כשכופלים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span></span> או כשמחסרים אותה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: בטענה 3 מותר שאחת תהיה קבועה שלילית!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בטענה 3 מותר שאחת תהיה קבועה שלילית!</p><div class=\"callout-body\"><p>בטענה 3 קחו פונקציה קבועה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-1\\)</span> (האם קבוע חסום מלרע? כן!) ופוקנציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> מה יוצא המכפלה?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את כל שלוש הטענות בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>:</span> הפונקציות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> כולן חסומות מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> אבל בגלל הסימן השלילי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;0\\)</span>,</span> מינוס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span>,</span> וכפל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span></span> שלוש התוצאות מתנהגות כמו <span class=\"math math-inline\" dir=\"ltr\">\\(-x\\)</span> ואינן חסומות מלרע.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: לא נכונה.</strong> קחו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=-1&lt;0\\)</span>.</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> (על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span> עם זאת, <span class=\"math math-inline\" dir=\"ltr\">\\(c\\cdot f(x)=-x\\)</span> אינה חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m\\in\\mathbb R\\)</span>,</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\max\\{1,|m|\\}+1\\in I\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\cdot f(x)=-x&lt;-|m|-1&lt;m\\)</span>.</span></p>\n<p><strong>טענה 2: לא נכונה.</strong> קחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span>.</span></span> שתיהן מקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge 0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\)</span>,</span> ולכן שתיהן חסומות מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span> אבל ההפרש הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-g(x)=-x\\)</span>,</span> שכמו בסעיף 1 אינו חסום מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><em>למה?</em> חיבור שתי חסומות מלרע נשאר חסום מלרע, אבל בחיסור <span class=\"math math-inline\" dir=\"ltr\">\\(f-g\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(-g\\)</span> חסומה מלעיל (ויכולה לברוח <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>).</span></span></p>\n<p><strong>טענה 3: לא נכונה.</strong> קחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span>.</span></span> הפונקציה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-1\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> (למשל על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span></span> חסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> המכפלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\cdot g(x)=-x\\)</span>,</span> שאינה חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ח</strong>).</p></div></div>","steps":["<p><strong>טענה 1: לא נכונה.</strong> קחו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=-1&lt;0\\)</span>.</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> (על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span> עם זאת, <span class=\"math math-inline\" dir=\"ltr\">\\(c\\cdot f(x)=-x\\)</span> אינה חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m\\in\\mathbb R\\)</span>,</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\max\\{1,|m|\\}+1\\in I\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\cdot f(x)=-x&lt;-|m|-1&lt;m\\)</span>.</span></p>","<p><strong>טענה 2: לא נכונה.</strong> קחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span>.</span></span> שתיהן מקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge 0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in I\\)</span>,</span> ולכן שתיהן חסומות מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span>.</span></span> אבל ההפרש הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-g(x)=-x\\)</span>,</span> שכמו בסעיף 1 אינו חסום מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><em>למה?</em> חיבור שתי חסומות מלרע נשאר חסום מלרע, אבל בחיסור <span class=\"math math-inline\" dir=\"ltr\">\\(f-g\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(-g\\)</span> חסומה מלעיל (ויכולה לברוח <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>).</span></span></p>","<p><strong>טענה 3: לא נכונה.</strong> קחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(I=(0,\\infty)\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span>.</span></span> הפונקציה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-1\\)</span> חסומה מלרע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(I\\)</span></span> (למשל על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>),</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span></span> חסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> המכפלה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\cdot g(x)=-x\\)</span>,</span> שאינה חסומה מלרע <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: אף טענה אינה נכונה (תשובה <strong>ח</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לקרוא ברפרוף את טענה 2 <span class=\"nobr\">כ-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)+g(x)\\)</span></span> במקום <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-g(x)\\)</span> ולסמן בטעות שהיא נכונה.</li><li>לחשוב ש-&quot;חסומות מלרע&quot; פירושו &quot;חסומות&quot; או &quot;אי-שליליות&quot; — פונקציה יכולה להיות חסומה מלרע וגם שלילית (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>)</span> או לא חסומה מלעיל (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>).</span></li></ul></div></div>"}],"similar":"","mc":{"1":false,"2":false,"3":false}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}\\left(\\sqrt{x+25}-4\\right)^{\\frac{10}{x}} &amp; x&gt;0 \\\\ e &amp; x=0 \\\\ 3^{\\frac{a}{x}}+e+x\\sin\\left(\\frac{a}{x}\\right) &amp; x&lt;0.\\end{cases}\\]</div>\n<p>א. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ב. עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ג. אף אחת מהטענות הנ&quot;ל אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שני הצדדים צריכים לנחות בדיוק בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> כדי שהפונקציה תהיה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> מצד ימין זה אכן מגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span></span> ומצד שמאל <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span></span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> שואף למינוס אינסוף ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(3^{a/x}\\)</span> נעלם ונשאר בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שני הצדדים צריכים לנחות בדיוק בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> כדי שהפונקציה תהיה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> מצד ימין זה אכן מגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span></span> ומצד שמאל <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span></span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> שואף למינוס אינסוף ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(3^{a/x}\\)</span> נעלם ונשאר בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: מימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>)</span> הולך רכבת שמגיעה אל התחנה בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span> משמאל <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>)</span> יש תוספת של <span class=\"math math-inline\" dir=\"ltr\">\\(3^{a/x}\\)</span> ורעש קטן <span class=\"math math-inline\" dir=\"ltr\">\\(x\\sin(a/x)\\)</span> על הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>,</span> התוספת נתקעת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3^0=1\\)</span>,</span> כך שהגובה משמאל הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1+e\\)</span> ויש מדרגה בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> אבל אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>,</span> בגלל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> שלילי, המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> נעשית שלילית ענקית, החזקה <span class=\"math math-inline\" dir=\"ltr\">\\(3^{\\text{ענק שלילי}}\\)</span> מתאפסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> והרכבת נוחתת חלק לגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>!</span></p>\n<p><strong>עם מספרים</strong>: מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt{25.01}-4)^{1000}\\approx 1.001^{1000}\\approx 2.717\\approx e\\)</span>.</span> משמאל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.01\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3^{-100}+e-0.01\\sin(-100)\\approx 0+e+0=e\\)</span>.</span> לעומת זאת עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> יוצא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3^0+e+0=1+e\\)</span>.</span></p>\n<p><strong>רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span></strong> מתקיימת אם ורק אם הגבול מימין, הגבול משמאל והערך <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span> כולם שווים זה לזה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>העקומה הכחולה (<span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>)</span></span> מגיעה חלק אל התחנה הירוקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,e)\\)</span>,</span> והעקומה האדומה (<span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>)</span></span> מתקרבת מצד שמאל. כשהפרמטר <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> חיובי (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=1\\)</span>),</span> שתי העקומות נפגשות יפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,e)\\)</span>.</span></span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וראו איך העקומה האדומה קופצת מיד כלפי מעלה אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e\\)</span>!</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-3,&quot;xmax&quot;:3,&quot;ymin&quot;:0,&quot;ymax&quot;:6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a=1&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-1,&quot;max&quot;:2,&quot;step&quot;:0.5}},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;r(x)=(\\\\sqrt{x+25}-4)^{\\\\frac{10}{x}}+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;l(x)=3^{\\\\frac{a}{x}}+e+x\\\\cdot\\\\sin\\\\left(\\\\frac{a}{x}\\\\right)+0\\\\cdot\\\\sqrt{-x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;pe&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,2.7183)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;(0, e)&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קודם בודקים את הגבול מימין","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קודם בודקים את הגבול מימין</p><div class=\"callout-body\"><p>בענף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> פרקו <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x+25}-4=1+(\\sqrt{x+25}-5)\\)</span> והכפילו בצמוד כדי לקבל את תבנית הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> (טענה 6.18). האם הגבול מימין שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: זהירות בסימן של $x$ בגבול משמאל!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: זהירות בסימן של <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בגבול משמאל!</p><div class=\"callout-body\"><p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span>,</span></span> המשתנה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> הוא <strong>שלילי</strong>. לכן <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>,</span></span> מהו הסימן של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span>,</span> ולאן שואף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3^{\\frac{a}{x}}\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נחשב תחילה את הגבול מימין (הוא יצא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e=f(0)\\)</span>).</span> אחר כך נבדוק את הגבול משמאל עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> (יצא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e\\ne e\\)</span>,</span> נפסל) ועבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>:</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>,</span> השבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\to-\\infty\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3^{a/x}\\to 0\\)</span>,</span> והאיבר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\sin(a/x)\\to 0\\)</span> (אפסה כפול חסומה), כך שהגבול משמאל הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span> מכאן שבמצב <span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span> הפונקציה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: חישוב הגבול מימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>).</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt{x+25}-4=1+(\\sqrt{x+25}-5)=1+\\frac{x+25-25}{\\sqrt{x+25}+5}=1+\\frac{x}{\\sqrt{x+25}+5}.\\]</div>\n<p>נכתוב את הענף של <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> באמצעות הגבול הסטנדרטי <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to 0}(1+t)^{\\frac1t}=e\\)</span> (טענה 6.18 וטענה 6.15):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left(\\sqrt{x+25}-4\\right)^{\\frac{10}{x}}=\\left[\\left(1+\\frac{x}{\\sqrt{x+25}+5}\\right)^{\\frac{\\sqrt{x+25}+5}{x}}\\right]^{\\frac{10}{\\sqrt{x+25}+5}}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x}{\\sqrt{x+25}+5}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (ושונה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>),</span> ולכן הבסיס שבתוך הסוגריים שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span></span> המעריך שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{10}{\\sqrt{25}+5}=\\frac{10}{10}=1\\)</span>.</span></span> מכאן ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}f(x)=e^1=e=f(0).\\]</div>\n<p><strong>שלב 2: בדיקת אפשרות א <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>).</span></strong> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> בענף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=3^{\\frac{0}{x}}+e+x\\sin\\left(\\frac{0}{x}\\right)=3^0+e+0=1+e.\\]</div>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)=1+e\\ne e=f(0)\\)</span>,</span> ומכאן שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> הפונקציה אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>שלב 3: בדיקת אפשרות ב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>).</span></strong> נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>:</span></p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span></span> (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>),</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}\\frac{a}{x}=-\\infty\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}3^{\\frac{a}{x}}=0\\)</span> (תכונת הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(3^u\\to 0\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u\\to-\\infty\\)</span>).</span></span></li><li>בנוסף, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|x\\sin\\left(\\frac{a}{x}\\right)\\right|\\le |x|\\to 0\\)</span>,</span> ולכן ממשפט הסנדוויץ׳ (אפסה כפול חסומה) <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}x\\sin\\left(\\frac{a}{x}\\right)=0\\)</span>.</span></li></ul>\n<p><em>למה?</em> אף שהזווית <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> משתוללת ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> הסינוס תמיד כלוא בין <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> והכפל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> מוחץ אותו לאפס.</p>\n<p>מאריתמטיקה של גבולות נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-}f(x)=0+e+0=e=f(0)=\\lim_{x\\to 0^+}f(x).\\]</div>\n<p>שלושת הערכים שווים, ולכן עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (תשובה <strong>ב</strong>).</p></div></div>","steps":["<p><strong>שלב 1: חישוב הגבול מימין <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>).</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt{x+25}-4=1+(\\sqrt{x+25}-5)=1+\\frac{x+25-25}{\\sqrt{x+25}+5}=1+\\frac{x}{\\sqrt{x+25}+5}.\\]</div>\n<p>נכתוב את הענף של <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> באמצעות הגבול הסטנדרטי <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to 0}(1+t)^{\\frac1t}=e\\)</span> (טענה 6.18 וטענה 6.15):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left(\\sqrt{x+25}-4\\right)^{\\frac{10}{x}}=\\left[\\left(1+\\frac{x}{\\sqrt{x+25}+5}\\right)^{\\frac{\\sqrt{x+25}+5}{x}}\\right]^{\\frac{10}{\\sqrt{x+25}+5}}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span>,</span></span> הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x}{\\sqrt{x+25}+5}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (ושונה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>),</span> ולכן הבסיס שבתוך הסוגריים שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span></span> המעריך שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{10}{\\sqrt{25}+5}=\\frac{10}{10}=1\\)</span>.</span></span> מכאן ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^+}f(x)=e^1=e=f(0).\\]</div>","<p><strong>שלב 2: בדיקת אפשרות א <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>).</span></strong> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> בענף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=3^{\\frac{0}{x}}+e+x\\sin\\left(\\frac{0}{x}\\right)=3^0+e+0=1+e.\\]</div>\n<p>לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)=1+e\\ne e=f(0)\\)</span>,</span> ומכאן שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> הפונקציה אינה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>","<p><strong>שלב 3: בדיקת אפשרות ב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>).</span></strong> נחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}f(x)\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>:</span></p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span></span> (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>),</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}\\frac{a}{x}=-\\infty\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}3^{\\frac{a}{x}}=0\\)</span> (תכונת הפונקציה המעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(3^u\\to 0\\)</span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u\\to-\\infty\\)</span>).</span></span></li><li>בנוסף, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|x\\sin\\left(\\frac{a}{x}\\right)\\right|\\le |x|\\to 0\\)</span>,</span> ולכן ממשפט הסנדוויץ׳ (אפסה כפול חסומה) <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^-}x\\sin\\left(\\frac{a}{x}\\right)=0\\)</span>.</span></li></ul>\n<p><em>למה?</em> אף שהזווית <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> משתוללת ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> הסינוס תמיד כלוא בין <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> והכפל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> מוחץ אותו לאפס.</p>\n<p>מאריתמטיקה של גבולות נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0^-}f(x)=0+e+0=e=f(0)=\\lim_{x\\to 0^+}f(x).\\]</div>\n<p>שלושת הערכים שווים, ולכן עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></p>\n<p><strong>התשובה במבחן</strong>: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (תשובה <strong>ב</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח שבענף משמאל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> הוא <strong>שלילי</strong>, ולכן לחשוב <span class=\"nobr\">שכש-<span class=\"math math-inline\" dir=\"ltr\">\\(a&gt;0\\)</span></span> המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a}{x}\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span> במקום <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>.</span></span></li><li>לא לסדר את המעריך בענף מימין ולהישאר עם צורה של <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span> בלי לעבור דרך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to 0}(1+t)^{1/t}=e\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"answer":"ב"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><ol><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le a&lt;b\\le\\pi\\)</span> מתקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin b-\\sin a|&lt;|b-a|\\)</span>.</span></li><li>קיימת פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{-x}+\\cos^2 x\\right)\\right)=1\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בטענה 1, שיפוע הסינוס בתוך הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span> תמיד קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בערך מוחלט, כך שהשינוי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span></span> קטן ממש מהשינוי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>.</span></span> בטענה 2, במקום להסתבך עם <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span> שבמינוס אינסוף מתפוצץ, פשוט בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span> (שנשארת בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בכל העולם) והיא משלימה את <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos^2 x\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span></span> נעלם לאפס!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בטענה 1, שיפוע הסינוס בתוך הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span> תמיד קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בערך מוחלט, כך שהשינוי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span></span> קטן ממש מהשינוי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>.</span></span> בטענה 2, במקום להסתבך עם <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span> שבמינוס אינסוף מתפוצץ, פשוט בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span> (שנשארת בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בכל העולם) והיא משלימה את <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos^2 x\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בזמן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span></span> נעלם לאפס!</p>\n<p><strong>תמונה בראש</strong>: בטענה 1, גל הסינוס הוא מדרון רגוע ששיפועו המרבי <span class=\"math math-inline\" dir=\"ltr\">\\(\\pm 1\\)</span> קורה רק ממש על הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi\\)</span>;</span></span> בכל נקודה באמצע המדרון מתון יותר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולכן אף מיתר בתוך <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\pi]\\)</span> לא יכול להיות בשיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> בטענה 2, צריך להביא פונקציה חסומה שתאזן את <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos^2 x\\)</span> — לוקחים את החבר הטבעי שלו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin^2 x\\)</span>,</span> שתמיד משלים אותו בדיוק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ונותנים לזנב <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span> לדעוך לבדו.</p>\n<p><strong>עם מספרים</strong>: בטענה 1, נציב <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\frac{\\pi}{2}\\approx 1.57\\)</span>:</span></span> ההפרש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> והוא קטן ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.57\\)</span>.</span></span> בטענה 2, עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span>:</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le f(x)\\le 1\\)</span>,</span> והסכום הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^{-x}\\)</span>,</span> <span class=\"nobr\">שכש-<span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span></span> כבר שווה <span class=\"math math-inline\" dir=\"ltr\">\\(1.000045\\)</span> — בדרכו <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>פונקציה חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></strong> צריכה להיות חסומה בכל הישר הממשי, כולל עבור מספרים שליליים ענקיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to-\\infty\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף (טענה 1)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענה 1)</span></summary><div class=\"callout-body\"><p>הגרף הכחול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span> בין הקווים האפורים <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\pi\\)</span>.</span></span> מהנקודה <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\sin a)\\)</span> יוצא משפך הקווים האדומים המקווקווים בשיפועי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pm 1\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span> בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\pi]\\)</span>:</span> הנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((b,\\sin b)\\)</span> תמיד נשארת ממש בתוך המשפך האדום — כלומר הפרש הגבהים קטן ממש מהמרחק האופקי!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:3.4,&quot;ymin&quot;:-1.5,&quot;ymax&quot;:2.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a=0.4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0,&quot;max&quot;:1.5,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;b=2.1&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1.6,&quot;max&quot;:3.1,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\sin(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(a)+(x-a)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(a)-(x-a)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;w&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=\\\\pi&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(a,f(a))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(b,f(b))&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"},{"title":"רואים את זה בגרף (טענה 2)","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף (טענה 2)</span></summary><div class=\"callout-body\"><p>הפונקציה האדומה היא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span> (חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> על כל הישר!), הפונקציה הכחולה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=e^{-x}+\\cos^2 x\\)</span>,</span> והסכום הירוק שלהן <span class=\"math math-inline\" dir=\"ltr\">\\(1+e^{-x}\\)</span> צונח מיד אל הקו האפור המקווקו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1.4,&quot;xmax&quot;:6,&quot;ymin&quot;:-0.2,&quot;ymax&quot;:4}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=(\\\\sin(x))^2&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=e^{-x}+(\\\\cos(x))^2&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;s&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(x)+g(x)&quot;,&quot;color&quot;:&quot;#388c46&quot;},{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: משפט לגראנז׳ בטענה 1","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: משפט לגראנז׳ בטענה 1</p><div class=\"callout-body\"><p>הפעילו את משפט לגראנז׳ (משפט 8.6) על <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> היכן נמצאת נקודת הביניים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>?</span> שימו לב שהיא בקטע <strong>הפתוח</strong> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\subseteq(0,\\pi)\\)</span>!</span></p></div></div>"},{"title":"רמז 2: מלכודת $e^{-x}$ בטענה 2!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מלכודת <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}\\)</span> בטענה 2!</p><div class=\"callout-body\"><p>אם תבחרו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-e^{-x}-\\cos^2 x\\)</span>,</span> מה יקרה לה <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to-\\infty\\)</span>?</span></span> הגדירו במקום זאת <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span> (או אפסו את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>).</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את טענה 1 ממשפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span>:</span> נקודת הביניים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> שייכת לקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span>,</span> שבו <span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos c|&lt;1\\)</span> ממש, ומכאן אי-שוויון חזק. נוכיח את טענה 2 על ידי הבחירה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span>:</span> היא חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> והסכום מתפשט <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^{-x}\\to 1\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: נכונה.</strong> יהיו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le a&lt;b\\le\\pi\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span> רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.26), ובפרט בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sin b-\\sin a=\\cos c\\cdot(b-a).\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le a&lt;c&lt;b\\le\\pi\\)</span>,</span></span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> נמצאת בקטע <strong>הפתוח</strong> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span>.</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x\\)</span> יורדת ממש (כי <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)'=-\\sin x&lt;0\\)</span> שם), ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,\\pi)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-1=\\cos\\pi&lt;\\cos c&lt;\\cos 0=1,\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos c|&lt;1\\)</span> באי-שוויון חזק. מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b-a|&gt;0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|\\sin b-\\sin a|=|\\cos c|\\cdot|b-a|&lt;1\\cdot|b-a|=|b-a|.\\]</div>\n<p><em>למה?</em> גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\pi\\)</span>,</span> משפט לגראנז׳ מבטיח שהשיפוע מתקבל בנקודה פנימית ממש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span>,</span> שבה הקוסינוס אינו יכול להיות <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>.</span></p>\n<p><strong>טענה 2: נכונה.</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\sin^2 x.\\]</div>\n<p>ראשית, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le\\sin^2 x\\le 1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p>\n<p>שנית, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> מהזהות <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin^2 x+\\cos^2 x=1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)+\\left(e^{-x}+\\cos^2 x\\right)=\\sin^2 x+\\cos^2 x+e^{-x}=1+e^{-x}.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}e^{-x}=0\\)</span>,</span></span> מקבלים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{-x}+\\cos^2 x\\right)\\right)=\\lim_{x\\to\\infty}(1+e^{-x})=1+0=1.\\]</div>\n<p><strong>התשובה במבחן</strong>: שתי הטענות נכונות (תשובה <strong>ג</strong>).</p></div></div>","steps":["<p><strong>טענה 1: נכונה.</strong> יהיו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le a&lt;b\\le\\pi\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span> רציפה וגזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.26), ובפרט בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span> כך ש-:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sin b-\\sin a=\\cos c\\cdot(b-a).\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le a&lt;c&lt;b\\le\\pi\\)</span>,</span></span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> נמצאת בקטע <strong>הפתוח</strong> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span>.</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\pi)\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x\\)</span> יורדת ממש (כי <span class=\"math math-inline\" dir=\"ltr\">\\((\\cos x)'=-\\sin x&lt;0\\)</span> שם), ולכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,\\pi)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-1=\\cos\\pi&lt;\\cos c&lt;\\cos 0=1,\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos c|&lt;1\\)</span> באי-שוויון חזק. מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|b-a|&gt;0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|\\sin b-\\sin a|=|\\cos c|\\cdot|b-a|&lt;1\\cdot|b-a|=|b-a|.\\]</div>\n<p><em>למה?</em> גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b=\\pi\\)</span>,</span> משפט לגראנז׳ מבטיח שהשיפוע מתקבל בנקודה פנימית ממש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span>,</span> שבה הקוסינוס אינו יכול להיות <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>.</span></p>","<p><strong>טענה 2: נכונה.</strong> נבחר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\sin^2 x.\\]</div>\n<p>ראשית, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le\\sin^2 x\\le 1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p>\n<p>שנית, לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> מהזהות <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin^2 x+\\cos^2 x=1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)+\\left(e^{-x}+\\cos^2 x\\right)=\\sin^2 x+\\cos^2 x+e^{-x}=1+e^{-x}.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}e^{-x}=0\\)</span>,</span></span> מקבלים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}\\left(f(x)+\\left(e^{-x}+\\cos^2 x\\right)\\right)=\\lim_{x\\to\\infty}(1+e^{-x})=1+0=1.\\]</div>\n<p><strong>התשובה במבחן</strong>: שתי הטענות נכונות (תשובה <strong>ג</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>בטענה 1, לחשוב שבגלל שקצות הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\pi]\\)</span> סגורים <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos 0=1\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos \\pi|=1\\)</span>,</span> אז אפשר לקבל שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin b-\\sin a|=|b-a|\\)</span> והטענה שקרית. נקודת לגראנז׳ <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> תמיד נמצאת בקטע <strong>הפתוח</strong> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></li><li>בטענה 2, לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-e^{-x}-\\cos^2 x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>:</span> עבור בחירה זו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to-\\infty}f(x)=-\\infty\\)</span>,</span> כך שהיא <strong>אינה חסומה</strong> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>!</span></span> צריך לחסום <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span></span> או פשוט לבחור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin^2 x\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"1":true,"2":true}},"10":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה המוגדרת בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<ol><li>אם לכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span>,</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></li><li>אם לכל קטע <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span>,</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></li></ol>\n<p>הטענות הנכונות הן: א. 1 ב. 2 ג. 1,2 ד. אף טענה אינה נכונה</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הפעם מותר לבחור את הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> כולו בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>:</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span> שני הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(b)\\)</span></span> לא יכולים לשבור את החסימות — אבל אף קטע פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> לא מכיל את הקצוות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\)</span>,</span> ולכן היא יכולה לקפוץ שם ולהישאר לא רציפה!</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הפעם מותר לבחור את הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> כולו בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>:</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span> שני הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(b)\\)</span></span> לא יכולים לשבור את החסימות — אבל אף קטע פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> לא מכיל את הקצוות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\)</span>,</span> ולכן היא יכולה לקפוץ שם ולהישאר לא רציפה!</p>\n<p><strong>תמונה בראש</strong>: דמיינו אולם ארוך <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> עם שני עמודים בודדים בדלת הכניסה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>)</span> ובדלת היציאה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>).</span> אם אתם יודעים שכל הגבהים בכל האולם הפנימי <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> נכנסים מתחת לתקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\)</span>,</span> הוספת שני עמודים בודדים בגובה סופי לא תיצור תקרה אינסופית. אבל אם בדקתם רק שכל מה שבתוך החדר <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> חלק בלי קפיצות, לא הסתכלתם בכלל על מדרגות הכניסה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> <span class=\"nobr\">וב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> ושם עלולה להיות מדרגה פתאומית!</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span></span> אם מגדירים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,2]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>,</span></span> אז על כל קטע פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[0,2]\\)</span> הפונקציה היא האפס הקבוע (רציפה וחסומה), והיא אכן חסומה בכל <span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span> (בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span></span> אבל היא לא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי הגבול מימין הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\ne 1=f(0)\\)</span>.</span></p>\n<p><strong>רציפות בקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></strong> דורשת גם רציפות בכל נקודה פנימית, וגם רציפות מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> ומשמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף של הפונקציה מהדוגמה הנגדית: כולה יושבת על הקו הכחול <span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span> בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2]\\)</span>,</span> אבל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> היא קופצת לנקודה האדומה <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ומשאירה חור ריק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span></span> כל חלון פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,1.8)\\)</span> שתזיזו (דרך המחוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>)</span> רואה רק קו חלק ושטוח, ובכל זאת בקצה השמאלי יש קפיצה!</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.2,&quot;ymin&quot;:-0.5,&quot;ymax&quot;:1.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;c&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;c=0.2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:0.9,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=0&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;wa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wc&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=c&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;wd&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1.8&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;hole&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;},{&quot;id&quot;:&quot;jump&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true,&quot;label&quot;:&quot;f(0) = 1&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איזה קטע פתוח הכי גדול מוכל ב-$[a,b]$?","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איזה קטע פתוח הכי גדול מוכל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>?</span></span></p><div class=\"callout-body\"><p>שימו לב: הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> עצמו הוא קטע פתוח המקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\subset[a,b]\\)</span>!</span></p></div></div>"},{"title":"רמז 2: למה הקצוות $a$ ו-$b$ מפרידים בין חסימות לרציפות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> מפרידים בין חסימות לרציפות</p><div class=\"callout-body\"><p>חסימות של קבוצה משתמרת כשמוסיפים לה שתי נקודות בודדות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(b)\\)</span>).</span></span> אבל רציפות בקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> דורשת גם התאמה בגבולות החד-צדדיים בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>!</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את טענה 1 על ידי בחירת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)=(a,b)\\subset[a,b]\\)</span>:</span> מהנתון <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\)</span>,</span> והוספת שתי נקודות הקצה נותנת חסם סופי <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\max\\{M_0,|f(a)|,|f(b)|\\}\\)</span> על כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> נפריך את טענה 2 עם פונקציה שקופצת בנקודת הקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>:</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span> היא קבועה ורציפה, אבל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> אינה רציפה מימין.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>טענה 1: נכונה.</strong> הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> מוכל ממש בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\notin(a,b)\\)</span> והם נמצאים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>).</span></span> לכן מותר להציב בנתון <span class=\"math math-inline\" dir=\"ltr\">\\(c=a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(d=b\\)</span>:</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\subset[a,b]\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p>\n<p>מכאן שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\ge 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_0\\)</span>.</span></p>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מוגדרת גם בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(a),f(b)\\in\\mathbb R\\)</span> הם שני מספרים סופיים. נגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M=\\max\\{M_0,|f(a)|,|f(b)|\\}.\\]</div>\n<p>אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]=(a,b)\\cup\\{a,b\\}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<p><em>למה?</em> בשונה מקטע פתוח (שבו לא מגיעים לקצוות ואפשר לטפס לאינסוף), כאן הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> כולו כבר מכוסה בחסם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\)</span>,</span> וחסרות רק שתי נקודות בדידות שאף פעם לא יכולות להפוך חסומה ללא-חסומה.</p>\n<p><strong>טענה 2: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}1 &amp; x=a \\\\ 0 &amp; a&lt;x\\le b.\\end{cases}\\]</div>\n<p>לכל קטע פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c&lt;d\\le b\\)</span>,</span> ולכן הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> אינה נמצאת בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subseteq(a,b)\\)</span>).</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> מתקיים אפוא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> באופן קבוע, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בכל קטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span>.</span></p>\n<p>עם זאת, בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=0\\ne 1=f(a)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>.</span></span> לפי הגדרה 5.26, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: טענה 1 בלבד נכונה (תשובה <strong>א</strong>).</p></div></div>","steps":["<p><strong>טענה 1: נכונה.</strong> הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> מוכל ממש בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (כי <span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\notin(a,b)\\)</span> והם נמצאים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>).</span></span> לכן מותר להציב בנתון <span class=\"math math-inline\" dir=\"ltr\">\\(c=a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(d=b\\)</span>:</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\subset[a,b]\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p>\n<p>מכאן שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\ge 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M_0\\)</span>.</span></p>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מוגדרת גם בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(a),f(b)\\in\\mathbb R\\)</span> הם שני מספרים סופיים. נגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M=\\max\\{M_0,|f(a)|,|f(b)|\\}.\\]</div>\n<p>אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]=(a,b)\\cup\\{a,b\\}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<p><em>למה?</em> בשונה מקטע פתוח (שבו לא מגיעים לקצוות ואפשר לטפס לאינסוף), כאן הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> כולו כבר מכוסה בחסם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0\\)</span>,</span> וחסרות רק שתי נקודות בדידות שאף פעם לא יכולות להפוך חסומה ללא-חסומה.</p>","<p><strong>טענה 2: לא נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\begin{cases}1 &amp; x=a \\\\ 0 &amp; a&lt;x\\le b.\\end{cases}\\]</div>\n<p>לכל קטע פתוח <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c&lt;d\\le b\\)</span>,</span> ולכן הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> אינה נמצאת בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> (כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subseteq(a,b)\\)</span>).</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\)</span> מתקיים אפוא <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> באופן קבוע, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בכל קטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c,d)\\subset[a,b]\\)</span>.</span></p>\n<p>עם זאת, בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)=0\\ne 1=f(a)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה מימין <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>.</span></span> לפי הגדרה 5.26, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: טענה 1 בלבד נכונה (תשובה <strong>א</strong>).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להתבלבל עם המצב ההפוך <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\([c,d]\\subset(a,b)\\)</span>,</span> כמו במועד 81), ולחשוב שבגלל שאולי נצמד לקצוות אז אפשר לברוח לאינסוף: כאן הנתון חל על <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> עצמו!</li><li>לשכוח שבהגדרה 5.26 רציפות בקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> כוללת גם רציפות מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> ומשמאל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> ולכן אי-רציפות בנקודת קצה פוסלת את הרציפות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></li></ul></div></div>"}],"similar":"","mc":{"1":true,"2":false}}};
